   'knowledge-assets/csgraduates/data-structure/data_structure-basic-algorithm', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/basic/algorithm/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-basic-algorithm.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-basic-algorithm", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-basic-algorithm.html", "html": true}')
