-- 数据结构 / 数据结构基本概念
SET @kp_id := 232;
UPDATE knowledge_point
SET description = '数据结构基本概念 💡 低优先级 不会直接考察类型，这里作为一个总览，帮助大家理清考题中会涉及到哪些数据结构。 数据结构 数据结构（Data Structure）是 存储、组织和管理数据的方式 ，它不仅决定了数据的存储形式，也影响数据访问和操作的效率。 分类 考试中涉及的数据结构可以分为以下几种： 线性结构 （元素之间有顺序关系） 数组（Array） ：连续内存，随机访问快，插入删除慢 链表（Linked List） ：节点通过指针连接，插入删除快，访问慢 栈（Stack） ：后进先出（LIFO），用于函数调用、表达式求值 队列（Queue） ：先进先出（FIFO），用于任务调度 双端队列（Deque） ：两端都可以操作 树形结构 （元素之间有层级关系） 二叉树（Binary Tree） 二叉搜索树（BST） 堆（Heap） ：优先队列实现 平衡树（AVL、红黑树） 图结构 （元素之间有网络关系） 有向图 / 无向图 邻接矩阵 / 邻接表存储 常用于路径搜索、社交网络建模 散列表（Hash Table） 通过哈希函数实现快速查找 常用于字典、缓存 ', sort_order = COALESCE(sort_order, 15)
WHERE id = 232;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
