   'knowledge-assets/csgraduates/data-structure/data_structure-basic-ds', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/basic/ds/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-basic-ds.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-basic-ds", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-basic-ds.html", "html": true}')
