-- 数据结构 / 定义
SET @kp_id := 250;
UPDATE knowledge_point
SET description = '定义 🔥 高优先级 真题练习 树和图都是每年必考，其定义是后续应用的基础，需牢固掌握 图的概念 以及 邻接矩阵和邻接表这两种 存储方式 。 图的概念 图 是由 顶点 和 边 组成的非线性数据结构。 顶点 有时也被称为节点，而 边 是连接图中任意两个节点的线或弧。更正式地说， 图 是由一组 顶点 ( V ) 和一组 边 ( E ) 组成的。图用 G ( E , V ) 表示。 补充 树和图的区别？ 树 是受限制的 图 类型，只是有更多的规则。每棵 树 都是一个 图 ，但不是所有的 图 都是 树 。链表、 树 和堆都是 图 的特殊情况。 在 图论 中，根据边的方向性、连接方式、顶点间的关系等，可以进一步划分出多种类型的图，并引入如 连通性 、 完全性 、 度数 等一系列关键概念。这些分类和术语有助于我们更好地理解 图的结构特点和应用场景，下面我们将逐一进行介绍。 方向 有向图 （directed graph）：边是有方向的，从一个定点指向另一个定点 无向图 （undirected graph）：边是没有方向的 连通性 连通图 （Connected G', sort_order = COALESCE(sort_order, 16)
WHERE id = 250;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (250, 'knowledge-html/csgraduates/data-structure/data_structure-graph-defs.html', '定义 🔥 高优先级 真题练习 树和图都是每年必考，其定义是后续应用的基础，需牢固掌握 图的概念 以及 邻接矩阵和邻接表这两种 存储方式 。 图的概念 图 是由 顶点 和 边 组成的非线性数据结构。 顶点 有时也被称为节点，而 边 是连接图中任意两个节点的线或弧。更正式地说， 图 是由一组 顶点 ( V ) 和一组 边 ( E ) 组成的。图用 G ( E , V ) 表示。 补充 树和图的区别？ 树 是受限制的 图 类型，只是有更多的规则。每棵 树 都是一个 图 ，但不是所有的 图 都是 树 。链表、 树 和堆都是 图 的特殊情况。 在 图论 中，根据边的方向性、连接方式、顶点间的关系等，可以进一步划分出多种类型的图，并引入如 连通性 、 完全性 、 度数 等一系列关键概念。这些分类和术语有助于我们更好地理解 图的结构特点和应用场景，下面我们将逐一进行介绍。 方向 有向图 （directed graph）：边是有方向的，从一个定点指向另一个定点 无向图 （undirected graph）：边是没有方向的 连通性 连通图 （Connected G', 'https://www.csgraduates.com/data_structure/graph/defs/',
   'knowledge-assets/csgraduates/data-structure/data_structure-graph-defs', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/graph/defs/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-graph-defs.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-graph-defs", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-graph-defs.html", "html": true}')
ON DUPLICATE KEY UPDATE
  html_ref = VALUES(html_ref),
  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
  asset_dir = VALUES(asset_dir),
  metadata = VALUES(metadata),
  update_time = CURRENT_TIMESTAMP;

-- 数据结构 / 算法和应用
SET @kp_id := 251;
UPDATE knowledge_point
SET description = '算法和应用 🔥 高优先级 图的应用就 四大天王 ：最小生成树、最短路径、拓扑排序 和 关键路径。需掌握这四种应用当中的 每个细节 。当然还有 DFS 和 BFS 这两种 遍历方式 也不能忽略。 DFS 深度优先搜索（Depth-First Search，简称 DFS ）是一种用于图的遍历和搜索的算法，它从图中的一个起始顶点开始，尽可能深地访问顶点，直到无法继续前进，然后回溯到之前的顶点，继续深入其他分支。 DFS 通常用递归或栈来实现，确保在深度方向上优先遍历。 以下是 DFS 算法的一般步骤： 从起始顶点开始，将其标记为已访问。 遍历与当前顶点相邻的未访问顶点，选择其中一个未访问顶点作为下一个深度遍历的目标，然后递归地进行 DFS 。 如果无法继续深度遍历（即当前顶点没有未访问的邻居），则回溯到上一个顶点，继续遍历其他未访问的邻居。 重复步骤 2 和步骤 3，直到所有顶点都被访问。 图中 DFS 实现的框架与 树的遍历 类似，不同点在于需要使用 数组记录已经访问过的节点，避免重复遍历： 图在 邻接矩阵 和 邻接表 中的 DFS 都遵循这个框架，', sort_order = COALESCE(sort_order, 17)
WHERE id = 251;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (251, 'knowledge-html/csgraduates/data-structure/data_structure-graph-operation.html', '算法和应用 🔥 高优先级 图的应用就 四大天王 ：最小生成树、最短路径、拓扑排序 和 关键路径。需掌握这四种应用当中的 每个细节 。当然还有 DFS 和 BFS 这两种 遍历方式 也不能忽略。 DFS 深度优先搜索（Depth-First Search，简称 DFS ）是一种用于图的遍历和搜索的算法，它从图中的一个起始顶点开始，尽可能深地访问顶点，直到无法继续前进，然后回溯到之前的顶点，继续深入其他分支。 DFS 通常用递归或栈来实现，确保在深度方向上优先遍历。 以下是 DFS 算法的一般步骤： 从起始顶点开始，将其标记为已访问。 遍历与当前顶点相邻的未访问顶点，选择其中一个未访问顶点作为下一个深度遍历的目标，然后递归地进行 DFS 。 如果无法继续深度遍历（即当前顶点没有未访问的邻居），则回溯到上一个顶点，继续遍历其他未访问的邻居。 重复步骤 2 和步骤 3，直到所有顶点都被访问。 图中 DFS 实现的框架与 树的遍历 类似，不同点在于需要使用 数组记录已经访问过的节点，避免重复遍历： 图在 邻接矩阵 和 邻接表 中的 DFS 都遵循这个框架，', 'https://www.csgraduates.com/data_structure/graph/operation/',
   'knowledge-assets/csgraduates/data-structure/data_structure-graph-operation', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/graph/operation/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-graph-operation.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-graph-operation", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-graph-operation.html", "html": true}')
