-- 数据结构 / 定义和基本操作
SET @kp_id := 235;
UPDATE knowledge_point
SET description = '定义和基本操作 💡 低优先级 了解线性表的概念，不会直接考察。还是会考察 顺序表 和 链表 这两种具体实现方案。 线性表定义 线性表 （Linear List）是 L 数据结构 中的一种基本结构。它是 零个或多个数据元素的有限序列 。通常， 线性表 中的 数据元素 之间是 有序的 ，它们之间存在着 前驱和后继的关系 。 L = ( a 1 ​ , a 2 ​ , ⋯ , a i ​ , a i + 1 ​ , ⋯ , a n ​ ) 特点： 个数有限 表中元素数据类型都相同 ，每个元素占有 相同大小的存储空间 仅讨论 元素间的逻辑关系 ，表中元素有 先后顺序 顺序表和链表 线性表分为顺序存储结构（又称 顺序表 ）和链式存储结构（又称为 链表 ）。 顺序表中的元素存储地址是 连续的 （存储在栈中），而链表的元素存储地址是 非连续的 （存储在堆中），元素节点中除了存储数据元素之外还存储相邻元素的地址信息。顺序表中数据之间的 逻辑关系 和 物理关系 是一致的，链表中数据元素的逻辑关系和物理关系并不一定一致。 上图中左边为顺序表，右边为链表。顺序表在内存', sort_order = COALESCE(sort_order, 18)
WHERE id = 235;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (235, 'knowledge-html/csgraduates/data-structure/data_structure-linearlist-def.html', '定义和基本操作 💡 低优先级 了解线性表的概念，不会直接考察。还是会考察 顺序表 和 链表 这两种具体实现方案。 线性表定义 线性表 （Linear List）是 L 数据结构 中的一种基本结构。它是 零个或多个数据元素的有限序列 。通常， 线性表 中的 数据元素 之间是 有序的 ，它们之间存在着 前驱和后继的关系 。 L = ( a 1 ​ , a 2 ​ , ⋯ , a i ​ , a i + 1 ​ , ⋯ , a n ​ ) 特点： 个数有限 表中元素数据类型都相同 ，每个元素占有 相同大小的存储空间 仅讨论 元素间的逻辑关系 ，表中元素有 先后顺序 顺序表和链表 线性表分为顺序存储结构（又称 顺序表 ）和链式存储结构（又称为 链表 ）。 顺序表中的元素存储地址是 连续的 （存储在栈中），而链表的元素存储地址是 非连续的 （存储在堆中），元素节点中除了存储数据元素之外还存储相邻元素的地址信息。顺序表中数据之间的 逻辑关系 和 物理关系 是一致的，链表中数据元素的逻辑关系和物理关系并不一定一致。 上图中左边为顺序表，右边为链表。顺序表在内存', 'https://www.csgraduates.com/data_structure/linearlist/def/',
   'knowledge-assets/csgraduates/data-structure/data_structure-linearlist-def', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/linearlist/def/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-linearlist-def.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-linearlist-def", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-linearlist-def.html", "html": true}')
