-- 数据结构 / 链式表示
SET @kp_id := 237;
UPDATE knowledge_point
SET description = '链式表示 🔥 高优先级 真题练习 链表的基础操作 （插入、删除这种）是选择题的常客，解答题中的算法设计也会涉及到链表的操作。 单链表定义 线性表的 链式表示 通常指的是使用 链表 来实现线性表。 链表 是由一系列 结点 组成的，每个 结点 都包含一个 数据元素 和一个指向下一个 结点 的 指针 。这种结构允许我们 动态地插入 和 删除元素 ，而不需要移动其他元素。 与顺序表不同，单链表中每个 结点 的存储空间都是 动态分配 的，即使用 c 语言中的 函数或者 c++ 中的 操作符。 动态分配 的空间存储在 进程的堆 中，这些 结点 占用的存储空间不是连续的，而是离散的，如下图所示： 由于堆的这种 动态内存分配 特性， 单链表 具备如下优点： 链表大小可以动态变化 ：链表的 结点 是在需要时 动态分配 的，因此在使用过程中不需要提前分配固定大小的存储空间，可以随时 插入 或 删除 结点 。 插入和删除方便 ：只要知道了某个 结点 的位置，就可以在 O(1) 的时间复杂度内 插入 或 删除 该 结点 。而顺序表可能需要移动大量的元素。 无需预估数据大', sort_order = COALESCE(sort_order, 19)
WHERE id = 237;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (237, 'knowledge-html/csgraduates/data-structure/data_structure-linearlist-linked.html', '链式表示 🔥 高优先级 真题练习 链表的基础操作 （插入、删除这种）是选择题的常客，解答题中的算法设计也会涉及到链表的操作。 单链表定义 线性表的 链式表示 通常指的是使用 链表 来实现线性表。 链表 是由一系列 结点 组成的，每个 结点 都包含一个 数据元素 和一个指向下一个 结点 的 指针 。这种结构允许我们 动态地插入 和 删除元素 ，而不需要移动其他元素。 与顺序表不同，单链表中每个 结点 的存储空间都是 动态分配 的，即使用 c 语言中的 函数或者 c++ 中的 操作符。 动态分配 的空间存储在 进程的堆 中，这些 结点 占用的存储空间不是连续的，而是离散的，如下图所示： 由于堆的这种 动态内存分配 特性， 单链表 具备如下优点： 链表大小可以动态变化 ：链表的 结点 是在需要时 动态分配 的，因此在使用过程中不需要提前分配固定大小的存储空间，可以随时 插入 或 删除 结点 。 插入和删除方便 ：只要知道了某个 结点 的位置，就可以在 O(1) 的时间复杂度内 插入 或 删除 该 结点 。而顺序表可能需要移动大量的元素。 无需预估数据大', 'https://www.csgraduates.com/data_structure/linearlist/linked/',
   'knowledge-assets/csgraduates/data-structure/data_structure-linearlist-linked', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/linearlist/linked/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-linearlist-linked.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-linearlist-linked", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-linearlist-linked.html", "html": true}')
