-- 数据结构 / 数组查找
SET @kp_id := 253;
UPDATE knowledge_point
SET description = '数组查找 ⭐ 中优先级 真题练习 在选择题中偶会考查，内容也不算难，关键在于掌握算法思想，也许会在算法设计题中间接考察到。 顺序查找 顺序查找的 核心思想 是从数组（线性表）的第一个元素开始，逐个检查每个元素是否等于目标值，直到找到目标或检查完整个数组。 其代码实现如下，非常简单，遍历一次数组即可： 顺序查找的 时间复杂度 如下： 最好情况 ： O ( 1 ) 最坏情况 ： O ( n ) 平均情况 ： O ( n ) 折半查找 折半查找 要求数组是有序的 。 其 核心思想 在于每次将查找范围折半，只保留目标可能存在的一半，直到范围为空或找到目标为止。 例如，在有序数组中查找一个元素时，可以先比较中间元素： 如果目标值小于中间值，查左半部分； 如果目标值大于中间值，查右半部分； 如果相等，则查找成功。 下图给出了一个实例，从数组中折半查找元素 23： 折半查找可以基于 迭代实现 ，也可以作为一个 递归函数实现 ： 折半查找的 时间复杂度 如下： 最好情况 ： O ( 1 ) 最坏情况 ： O ( l o g 2 ​ n ) 平均情况 ： O ( ', sort_order = COALESCE(sort_order, 21)
WHERE id = 253;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (253, 'knowledge-html/csgraduates/data-structure/data_structure-search-array.html', '数组查找 ⭐ 中优先级 真题练习 在选择题中偶会考查，内容也不算难，关键在于掌握算法思想，也许会在算法设计题中间接考察到。 顺序查找 顺序查找的 核心思想 是从数组（线性表）的第一个元素开始，逐个检查每个元素是否等于目标值，直到找到目标或检查完整个数组。 其代码实现如下，非常简单，遍历一次数组即可： 顺序查找的 时间复杂度 如下： 最好情况 ： O ( 1 ) 最坏情况 ： O ( n ) 平均情况 ： O ( n ) 折半查找 折半查找 要求数组是有序的 。 其 核心思想 在于每次将查找范围折半，只保留目标可能存在的一半，直到范围为空或找到目标为止。 例如，在有序数组中查找一个元素时，可以先比较中间元素： 如果目标值小于中间值，查左半部分； 如果目标值大于中间值，查右半部分； 如果相等，则查找成功。 下图给出了一个实例，从数组中折半查找元素 23： 折半查找可以基于 迭代实现 ，也可以作为一个 递归函数实现 ： 折半查找的 时间复杂度 如下： 最好情况 ： O ( 1 ) 最坏情况 ： O ( l o g 2 ​ n ) 平均情况 ： O ( ', 'https://www.csgraduates.com/data_structure/search/array/',
   'knowledge-assets/csgraduates/data-structure/data_structure-search-array', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/search/array/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-search-array.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-search-array", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-search-array.html", "html": true}')
ON DUPLICATE KEY UPDATE
  html_ref = VALUES(html_ref),
  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
