-- 数据结构 / 树形查找
SET @kp_id := 254;
UPDATE knowledge_point
SET description = '树形查找 ⭐ 中优先级 真题练习 在选择题中会考查，重点掌握两点：1. m 阶 B 树的特性 。2. B 树和 B+ 树的不同点和适用场景。 基于 BST 的查找 在 二叉查找树 以及它的改进版本 AVL 树、 红黑树 中，查找操作 都遵循相同的基本原则：利用 二叉树的有序性 来快速定位目标元素。 复习以下，二叉查找树具备以下特点： 左子树中所有节点的值 小于 根节点的值。 右子树中所有节点的值 大于 根节点的值。 这种「左小右大」的有序性，使得查找可以逐层缩小范围。 所以在基于二叉查找树进行查找时，过程如下： 从 根节点 开始。 如果查询的值 等于 当前节点的值，返回 当前节点 。 如果查询的值 小于 当前节点的值，向 左子树 查询。 如果查询的值 大于 当前节点的值，向 右子树 查询。 如果到达 空节点 ，则查询失败，返回 NULL 。 查找过程可以通过以下图示进行理解： BST查找时间复杂度分析 查找操作的时间复杂度，取决于树的 高度 （Height）： 树的高度越小，查找路径越短，效率越高。 树的高度越大（越“瘦长”），查找路径越长，效率', sort_order = COALESCE(sort_order, 23)
WHERE id = 254;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
