-- 数据结构 / 外部排序
SET @kp_id := 258;
UPDATE knowledge_point
SET description = '外部排序 ⭐ 中优先级 真题练习 其实外部排序不是高频考点，但是遭不住 23 年考了一道置换选择排序的大题，所以还是得掌握下 外部排序的过程 。这也给了我们一个启示：涉及到算法过程的知识点，都要留一个心眼，也许之前不考察但是今年就冷不丁地来一道大题。 外部排序 当待排序的数据量大到无法一次性全部装入内存时，就必须采用 外部排序 。外部排序的基本思路是：先将整个数据集划分成若干能够装入内存的子块，对每个子块在内存中完成内部排序；随后再把这些已排序的子块逐步合并，最终得到整体有序的结果。这样既克服了内存容量的限制，又能高效地对海量数据完成排序。 外部排序的整体过程通常可以划分为两个关键阶段： 生成初始归并段 先采用 置换选择排序 对原始的无序文件进行扫描。置换选择能够在一次扫描中尽可能长地生成有序子文件，这些子文件即称为 初始归并段 。每个归并段都是内部有序的，且长度尽量大，以减少后续合并的轮数。 多路归并 将所有 初始归并段 以多路归并的方式逐步合并。每一次归并都会把若干归并段合并成一个更长的有序段，重复此过程直至只剩下一个完整的有序文件，从而得到', sort_order = COALESCE(sort_order, 24)
WHERE id = 258;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (258, 'knowledge-html/csgraduates/data-structure/data_structure-sort-external.html', '外部排序 ⭐ 中优先级 真题练习 其实外部排序不是高频考点，但是遭不住 23 年考了一道置换选择排序的大题，所以还是得掌握下 外部排序的过程 。这也给了我们一个启示：涉及到算法过程的知识点，都要留一个心眼，也许之前不考察但是今年就冷不丁地来一道大题。 外部排序 当待排序的数据量大到无法一次性全部装入内存时，就必须采用 外部排序 。外部排序的基本思路是：先将整个数据集划分成若干能够装入内存的子块，对每个子块在内存中完成内部排序；随后再把这些已排序的子块逐步合并，最终得到整体有序的结果。这样既克服了内存容量的限制，又能高效地对海量数据完成排序。 外部排序的整体过程通常可以划分为两个关键阶段： 生成初始归并段 先采用 置换选择排序 对原始的无序文件进行扫描。置换选择能够在一次扫描中尽可能长地生成有序子文件，这些子文件即称为 初始归并段 。每个归并段都是内部有序的，且长度尽量大，以减少后续合并的轮数。 多路归并 将所有 初始归并段 以多路归并的方式逐步合并。每一次归并都会把若干归并段合并成一个更长的有序段，重复此过程直至只剩下一个完整的有序文件，从而得到', 'https://www.csgraduates.com/data_structure/sort/external/',
   'knowledge-assets/csgraduates/data-structure/data_structure-sort-external', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/sort/external/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-sort-external.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-sort-external", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-sort-external.html", "html": true}')
ON DUPLICATE KEY UPDATE
  html_ref = VALUES(html_ref),
  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
  asset_dir = VALUES(asset_dir),
  metadata = VALUES(metadata),
  update_time = CURRENT_TIMESTAMP;

-- 数据结构 / 内部排序
SET @kp_id := 257;
UPDATE knowledge_point
SET description = '内部排序 🔥 高优先级 真题练习 每年选择题都必考一到两题，需要能够辨别 不同排序算法的特征 以及掌握 每种排序算法执行的具体流程 。 排序概念 稳定性 排序算法的 稳定性 是指：在排序过程中， 如果两个元素的键值相等 ，排序后它们的 相对顺序保持不变 ，那么这个排序算法就是 稳定的排序算法 。 比如排序前的数组是这样： ，并且 和 的值相同。 如果排序后的数组是这样： ，那么排序算法就是不稳定的，反之排序算法就是 稳定的 。 补充 可以通过以下方式对排序算法的 稳定性 进行记忆： 速度比较快的算法（时间复杂度 O ( n l o g n ) ）一般都不稳定，除了 归并排序 ，因为它需要占额外的空间。 速度比较慢的算法（时间复杂度 O ( n 2 ) ）一般都稳定，除了 选择排序 。 除此之外， 桶排序 和 基数排序 都是 稳定的 。 元素移动次数 排序算法中的 元素移动次数 ，指的是在排序过程中对 数组元素进行位置变换的次数 。 下表列出了各排序算法的 元素移动次数 ： 排序算法 元素移动次数 说明 冒泡排序 最坏 O ( n 2 ) 每次交换', sort_order = COALESCE(sort_order, 25)
WHERE id = 257;
