   'knowledge-assets/csgraduates/data-structure/data_structure-sort-internal', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/sort/internal/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-sort-internal.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-sort-internal", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-sort-internal.html", "html": true}')
