-- 数据结构 / 模式匹配
SET @kp_id := 245;
UPDATE knowledge_point
SET description = '模式匹配 ⭐ 中优先级 真题练习 这一节要考的话其实就是 kmp 算法，会考察下 next 数组的构建 和 调整位置的方式 。虽然历年考查得其实也不是很多，但是这种涉及算法的还是得多留个心眼，因为有可能在今年的大题就考查了。 字符串模式匹配 是计算机科学中的基础问题，主要是在一个 主字符串 中查找一个 子字符串 模式。 串概念 在介绍模式匹配算法之前，需要能够区分关于串的几个概念： 主串 （Str / 主字符串）：待搜索的那一整段字符串。 子串 （Substr / 子字符串）：主串中的某一段字符串 模式串 （Pattern / 模式字符串）：要在主串中查找的目标。 以及以下几个关于 模式匹配 的术语： 匹配 ：在主串中找到与模式串完全相同的子串 匹配位置 ：模式串在主串中出现的起始位置 失配 ：当前字符不匹配 模式匹配算法 就是将 模式串 与 主串 相匹配，企图找到主串中的某个和 子串 和 模式串 完全相同。 简单模式匹配算法 简单模式匹配算法 （即暴力匹配 / 朴素匹配）的 基本思想 是：逐个检查 主串 的每一个位置，判断 从该位置开始的子串 ', sort_order = COALESCE(sort_order, 27)
WHERE id = 245;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
