-- 数据结构 / 树的应用
SET @kp_id := 248;
UPDATE knowledge_point
SET description = '树的应用 🔥 高优先级 真题练习 并查集其实没考过，编码方式和哈夫曼树也是高频考点。 编码和解码 编码 （Encoding）是将信息从一种形式（通常是人类可读的符号或数据）转换为另一种形式（通常是机器可处理的格式，如二进制比特流）的过程。其目的是为了便于存储、传输或处理信息。 编码 通常涉及将原始数据（如字符、数字等）映射为特定的代码，这些代码由一组 编码规则 定义。 解码 （Decoding）是编码的 逆过程 ，即将编码后的数据（如二进制比特流）转换回原始形式的过程。解码需要依赖编码时使用的规则或 编码表 ，以确保正确还原原始信息。 编码集分类 编码集 是一组用于表示特定符号或数据的 编码规则 的集合。 编码集 常按以下方式分类： 固定长度 vs 非固定长度 固定长度编码集 （定长）：每个代码的长度相同，例如 ASCII 编码中每个字符都用 8 位表示。 可变长度编码集 （变长）：代码长度可以不同，例如 哈夫曼编码 中高频符号用较短代码，低频符号用较长代码，以实现数据压缩。 前缀 vs 非前缀 前缀编码 ：没有一个编码是另一个编码的前缀 非前缀', sort_order = COALESCE(sort_order, 28)
WHERE id = 248;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (248, 'knowledge-html/csgraduates/data-structure/data_structure-tree-app.html', '树的应用 🔥 高优先级 真题练习 并查集其实没考过，编码方式和哈夫曼树也是高频考点。 编码和解码 编码 （Encoding）是将信息从一种形式（通常是人类可读的符号或数据）转换为另一种形式（通常是机器可处理的格式，如二进制比特流）的过程。其目的是为了便于存储、传输或处理信息。 编码 通常涉及将原始数据（如字符、数字等）映射为特定的代码，这些代码由一组 编码规则 定义。 解码 （Decoding）是编码的 逆过程 ，即将编码后的数据（如二进制比特流）转换回原始形式的过程。解码需要依赖编码时使用的规则或 编码表 ，以确保正确还原原始信息。 编码集分类 编码集 是一组用于表示特定符号或数据的 编码规则 的集合。 编码集 常按以下方式分类： 固定长度 vs 非固定长度 固定长度编码集 （定长）：每个代码的长度相同，例如 ASCII 编码中每个字符都用 8 位表示。 可变长度编码集 （变长）：代码长度可以不同，例如 哈夫曼编码 中高频符号用较短代码，低频符号用较长代码，以实现数据压缩。 前缀 vs 非前缀 前缀编码 ：没有一个编码是另一个编码的前缀 非前缀', 'https://www.csgraduates.com/data_structure/tree/app/',
   'knowledge-assets/csgraduates/data-structure/data_structure-tree-app', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/tree/app/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-tree-app.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-tree-app", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-tree-app.html", "html": true}')
