-- 数据结构 / 二叉树
SET @kp_id := 343;
UPDATE knowledge_point
SET description = '二叉树 🔥 高优先级 真题练习 树和图每年都是必考，这一节每个知识点都十分重要。 二叉树存储结构 链式存储结构 ： 链式存储是最常见的二叉树存储方式。在链式存储中，每个节点都包含一个数据元素以及指向其左子树和右子树的指针。 链式存储结构适用于表示任意形状和大小的二叉树，并且对于树的动态操作（插入、删除节点）非常方便。 顺序存储结构 （数组表示）： 顺序存储结构使用数组来表示二叉树。通常，数组的索引与二叉树的节点之间存在特定的关系，例如，对于索引 i 的节点，其左子节点在索引 2 i + 1 处，右子节点在索引 2 i + 2 处，父节点在索引 ( i − 1 ) / 2 处。 顺序存储结构通常用于堆数据结构（如二叉堆）的实现，其中对于堆的性质要求，使得数组表示变得非常有效。 链接存储 在 链接存储 中，我们需要在结构体中定义两个指针，分别指向二叉树左边的结点和右边的结点。 顺序存储 顺序存储表示用数组存储一颗树，如下图所示。 理解顺序存储的关键在于理解其 结点的隐式链接关系 以及 空指针的定义 这两点。 在顺序存储中，结点的链接关系由其下标指定：', sort_order = COALESCE(sort_order, 29)
WHERE id = 343;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
