   'knowledge-assets/csgraduates/data-structure/data_structure-tree-tree', '{"sourceName": "csgraduates", "subjectName": "数据结构", "sourceUrl": "https://www.csgraduates.com/data_structure/tree/tree/", "htmlRef": "knowledge-html/csgraduates/data-structure/data_structure-tree-tree.html", "assetDir": "knowledge-assets/csgraduates/data-structure/data_structure-tree-tree", "sourcePath": "knowledge-html-sources/csgraduates/data-structure/data_structure-tree-tree.html", "html": true}')
