-- 计算机组成原理 / 组成原理
SET @kp_id := 259;
UPDATE knowledge_point
SET description = '组成原理 计算机组成原理在 408 试卷中占据 45 分，和数据结构一样，是分数占比最大的科目，同样会考察 11 道选择题和两道大题。 大题的考察重点在与指令系统、CPU 以及存储系统。指令系统和 CPU 常常会放在一起考察，作为一道大题。存储系统系统常常会和操作系统中的相关知识在一起考察，在复习时可以将这两门课的相关内容放在一起复习。 计算机组成原理的考察目标包含如下内容（来自 408 考研大纲）： 掌握单处理器计算机系统中主要部件的工作原理、组成结构以及相互连接方式。 掌握指令集体系结构的基本知识和基本实现方法，对计算机硬件相关问题进行分析，并能够对相关部件进行设计。 理解计算机系统的整机概念，能够综合运用计算机组成的基本原理和基本方法，对高级编程语言（C 语言）程序中的相关问题进行分析，具备软硬件协同分析和设计能力。 概述 计算机组成原理的基本概念，可能会在选择题中考察，看到题目能够选出答案即可。 数据表示和计算 本章在选择题中考察，需要熟练掌握补码表示以及浮点数的 IEEE 标准。 存储系统 本章是重中之重，在选择题和大题中每年都会考察，', sort_order = COALESCE(sort_order, 31)
WHERE id = 259;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (259, 'knowledge-html/csgraduates/constitution-principle/constitution_principle.html', '组成原理 计算机组成原理在 408 试卷中占据 45 分，和数据结构一样，是分数占比最大的科目，同样会考察 11 道选择题和两道大题。 大题的考察重点在与指令系统、CPU 以及存储系统。指令系统和 CPU 常常会放在一起考察，作为一道大题。存储系统系统常常会和操作系统中的相关知识在一起考察，在复习时可以将这两门课的相关内容放在一起复习。 计算机组成原理的考察目标包含如下内容（来自 408 考研大纲）： 掌握单处理器计算机系统中主要部件的工作原理、组成结构以及相互连接方式。 掌握指令集体系结构的基本知识和基本实现方法，对计算机硬件相关问题进行分析，并能够对相关部件进行设计。 理解计算机系统的整机概念，能够综合运用计算机组成的基本原理和基本方法，对高级编程语言（C 语言）程序中的相关问题进行分析，具备软硬件协同分析和设计能力。 概述 计算机组成原理的基本概念，可能会在选择题中考察，看到题目能够选出答案即可。 数据表示和计算 本章在选择题中考察，需要熟练掌握补码表示以及浮点数的 IEEE 标准。 存储系统 本章是重中之重，在选择题和大题中每年都会考察，', 'https://www.csgraduates.com/constitution_principle/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle.html", "html": true}')
