-- 计算机组成原理 / 总线
SET @kp_id := 285;
UPDATE knowledge_point
SET description = '总线 🔥 高优先级 真题练习 本节几个概念是选择题常考点： 总线指标 、 总线分类 、 总线事务 、 总线定时 。 基本概念 总线 是一组电子导线或信号线，它们允许不同的硬件设备（如 CPU 、 内存 、 输入/输出 设备等）之间进行数据传输和通信。总线是计算机内部和外部设备之间的信息传递通道。 总线分类 功能 核内总线 ：在处理器核内部各元件之间连线的总线称为 核内总线 ，可连接核内各寄存器、ALU、指令部件等 系统总线 ：指连接 CPU 、主存和 I/O 接口等主要部件的总线，通常所说的总线是指这类在系统主要模块之间互连的总线。下面要介绍的也是这种 系统总线 。 通信总线 ：计算机系统之间或计算机系统与其他系统（远程通信设备、测试设备）之间进行通信的总线，又称 外部总线 。 数据传送方式 总线 的数据传输方式包含 串行 和 并行 两种： 串行总线 ：只含有一条双向数据线或两条单向数据线，数据按位分时传送。适合远距离通信，大多数 通信总线 属于 串行总线 并行总线 ：含有多条双向数据线，可实现多位同时传送。传输效率高，但相邻数据线之间会相互干扰', sort_order = COALESCE(sort_order, 38)
WHERE id = 285;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (285, 'knowledge-html/csgraduates/constitution-principle/constitution_principle-bus-bus.html', '总线 🔥 高优先级 真题练习 本节几个概念是选择题常考点： 总线指标 、 总线分类 、 总线事务 、 总线定时 。 基本概念 总线 是一组电子导线或信号线，它们允许不同的硬件设备（如 CPU 、 内存 、 输入/输出 设备等）之间进行数据传输和通信。总线是计算机内部和外部设备之间的信息传递通道。 总线分类 功能 核内总线 ：在处理器核内部各元件之间连线的总线称为 核内总线 ，可连接核内各寄存器、ALU、指令部件等 系统总线 ：指连接 CPU 、主存和 I/O 接口等主要部件的总线，通常所说的总线是指这类在系统主要模块之间互连的总线。下面要介绍的也是这种 系统总线 。 通信总线 ：计算机系统之间或计算机系统与其他系统（远程通信设备、测试设备）之间进行通信的总线，又称 外部总线 。 数据传送方式 总线 的数据传输方式包含 串行 和 并行 两种： 串行总线 ：只含有一条双向数据线或两条单向数据线，数据按位分时传送。适合远距离通信，大多数 通信总线 属于 串行总线 并行总线 ：含有多条双向数据线，可实现多位同时传送。传输效率高，但相邻数据线之间会相互干扰', 'https://www.csgraduates.com/constitution_principle/bus/bus/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-bus-bus', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/bus/bus/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-bus-bus.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-bus-bus", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-bus-bus.html", "html": true}')
ON DUPLICATE KEY UPDATE
