-- 计算机组成原理 / I/O 系统
SET @kp_id := 286;
UPDATE knowledge_point
SET description = 'I/O 系统 🔥 高优先级 真题练习 选择题高频考点，主要两点：1. IO 接口和端口 。2. 几种 IO 方式的细节和区别 。 此外，在解答题中偶尔也会结合总线指标考查一些计算过程，所以需要深入了解几种 IO 方式的细节。 输入/输出系统 以主机为中心 来看，将信息从外部设备传送到 主机 的过程称为 输入 ；将信息从 主机 传送到外部设备的过程称为 输出 。 简单架构 让我们首先来看一个早期简易 I/O 系统的架构（一般考查的也就是这种架构）： 在这个架构中，各部分的基本功能如下： 🔹 CPU 是整个计算机系统的控制和运算核心，它负责： 发出控制命令 （如读/写指令）以驱动外设；通过 I/O 总线 访问设备控制器 ，进行地址寻址、数据传输和状态监测；与 内存 协同， 完成数据的读取、处理与存储 。 🔹 外设 是计算机与外部世界交互的工具，例如键盘、打印机和磁盘等。它们接收来自 CPU 的输出（如打印任务），也能将物理信号（如按键动作）转换为数字信号传递给 CPU。 🔹 I/O 接口 是连接 主机 与 外设 之间信息传输的桥梁，负责协调两者之间的', sort_order = COALESCE(sort_order, 39)
WHERE id = 286;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (286, 'knowledge-html/csgraduates/constitution-principle/constitution_principle-bus-io.html', 'I/O 系统 🔥 高优先级 真题练习 选择题高频考点，主要两点：1. IO 接口和端口 。2. 几种 IO 方式的细节和区别 。 此外，在解答题中偶尔也会结合总线指标考查一些计算过程，所以需要深入了解几种 IO 方式的细节。 输入/输出系统 以主机为中心 来看，将信息从外部设备传送到 主机 的过程称为 输入 ；将信息从 主机 传送到外部设备的过程称为 输出 。 简单架构 让我们首先来看一个早期简易 I/O 系统的架构（一般考查的也就是这种架构）： 在这个架构中，各部分的基本功能如下： 🔹 CPU 是整个计算机系统的控制和运算核心，它负责： 发出控制命令 （如读/写指令）以驱动外设；通过 I/O 总线 访问设备控制器 ，进行地址寻址、数据传输和状态监测；与 内存 协同， 完成数据的读取、处理与存储 。 🔹 外设 是计算机与外部世界交互的工具，例如键盘、打印机和磁盘等。它们接收来自 CPU 的输出（如打印任务），也能将物理信号（如按键动作）转换为数字信号传递给 CPU。 🔹 I/O 接口 是连接 主机 与 外设 之间信息传输的桥梁，负责协调两者之间的', 'https://www.csgraduates.com/constitution_principle/bus/io/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-bus-io', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/bus/io/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-bus-io.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-bus-io", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-bus-io.html", "html": true}')
