SET @kp_id := 280;
UPDATE knowledge_point
SET description = '控制器 ⭐ 中优先级 真题练习 说实话，本节内容虽然多，但考察也没有那么频繁，主要关注 两点 ： 能够手写 寄存器传送语言 以及 指令执行各阶段的控制信号 ，这里国内的计组书中都没有直接说明，但是外国专业书籍有涉及，所以常常给考生造成困惑，这里杂货铺直接总结出精要，希望可以为你省下大量时间。 控制器的种类和区别 ，看到概念需要能区分出来。 主要功能 控制器是计算机系统的指挥中心， 控制器 的主要功能有： 指令解码 ： CPU 从存储器取出一个指令后，控制器负责 指令解码 这个指令，以确定要执行的操作和涉及的操作数。 生成控制信号 ： 基于 指令解码 的指令，控制器 生成控制信号 ，这些信号会驱动其他计算机部分（如算术逻辑单元、寄存器和存储器）按预期执行相应的操作。 时序控制 ： 通过先后发出不同的 时序控制 信号，确保指令的逻辑正确被执行， 根据控制器产生微操作 控制信号 方式的不同，控制器可以分为 硬布线控制器 和 微程序控制器 。 补充 用极为通俗的例子来对比， 控制器 就是 CPU 的“大脑”： 输入：控制器接收 机器指令 作为输入 输出：', sort_order = COALESCE(sort_order, 40)
WHERE id = 280;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
