-- 计算机组成原理 / 异常与中断
SET @kp_id := 281;
UPDATE knowledge_point
SET description = '异常与中断 🔥 高优先级 真题练习 本节也基本是选择题必考，要掌握 异常和中断的区别 ，就是概念上要区分开，不知道为啥，老头们很喜欢考这个。关于中断的具体介绍参考 组成原理相关章节 的内容。 异常 在 CPU 中， 异常 是指在程序执行过程中出现的非正常或意外情况，CPU 需要暂停当前执行，转而调用操作系统提供的异常处理程序。异常机制确保系统能够安全、有效地处理错误或特殊事件，并对程序执行做出相应调整。 类型 在执行指令的过程，可能发生如下五类异常： 除法错误 触发条件 ：程序尝试除以零或执行非法除法操作。 处理方式 ：通常由操作系统捕获并中断程序执行，可能显示错误信息或终止程序。 浮点异常 触发条件：浮点运算出现错误，例如溢出、下溢、除以零或非法操作（如对负数开平方）。 处理方式：操作系统可能中断程序、设置异常标志，或产生 NaN（非数）结果。 缺页异常 触发条件：程序访问的内存页尚未加载到物理内存中。 处理方式：操作系统会将所需页从磁盘调入内存，更新页表后恢复程序执行。 保护错误 触发条件：程序试图进行非法操作，如写入只读内存、访问内核空间或', sort_order = COALESCE(sort_order, 41)
WHERE id = 281;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
