-- 计算机组成原理 / 指令流水线
SET @kp_id := 282;
UPDATE knowledge_point
SET description = '指令流水线 🔥 高优先级 真题练习 流水线的考题包含 三大点 （重要） 和 两小点 ： 三大点：1. 在流水线中指令执行的 各个阶段 的细节。2. 时空图 的画法。3. 流水线冒险的种类和处理方法 。 两小点：1. 单周期和多周期处理器的概念。 2. 流水线指标。 指令执行阶段 指令的执行由很多按照时序进行的微操作组成，从逻辑角度进行划分，指令执行可以被分为 五个阶段 ： 取指（IF） ：从指令存储器获取指令并更新程序计数器。 译码（ID） ：解析指令、读取源寄存器并生成控制信号。 执行（EX） ：执行计算或分支逻辑，生成中间结果。 访存（MEM） ：执行内存读写操作，非内存指令为空。 写回（WB） ：将结果写回寄存器，非写回指令为空。 采用这五个阶段的流水线也叫做 五阶段流水线 。 取指 取指（IF）阶段的主要任务包括： 从指令存储器获取指令 ：根据程序计数器（PC）的值，从指令存储器（Instruction Memory）中读取当前指令。 更新程序计数器 （PC）：增加 PC 的值，指向下一条指令的地址。 传递指令 ：将读取的指令存储到 IF', sort_order = COALESCE(sort_order, 43)
WHERE id = 282;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (282, 'knowledge-html/csgraduates/constitution-principle/constitution_principle-cpu-pipeline.html', '指令流水线 🔥 高优先级 真题练习 流水线的考题包含 三大点 （重要） 和 两小点 ： 三大点：1. 在流水线中指令执行的 各个阶段 的细节。2. 时空图 的画法。3. 流水线冒险的种类和处理方法 。 两小点：1. 单周期和多周期处理器的概念。 2. 流水线指标。 指令执行阶段 指令的执行由很多按照时序进行的微操作组成，从逻辑角度进行划分，指令执行可以被分为 五个阶段 ： 取指（IF） ：从指令存储器获取指令并更新程序计数器。 译码（ID） ：解析指令、读取源寄存器并生成控制信号。 执行（EX） ：执行计算或分支逻辑，生成中间结果。 访存（MEM） ：执行内存读写操作，非内存指令为空。 写回（WB） ：将结果写回寄存器，非写回指令为空。 采用这五个阶段的流水线也叫做 五阶段流水线 。 取指 取指（IF）阶段的主要任务包括： 从指令存储器获取指令 ：根据程序计数器（PC）的值，从指令存储器（Instruction Memory）中读取当前指令。 更新程序计数器 （PC）：增加 PC 的值，指向下一条指令的地址。 传递指令 ：将读取的指令存储到 IF', 'https://www.csgraduates.com/constitution_principle/cpu/pipeline/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-cpu-pipeline', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/cpu/pipeline/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-cpu-pipeline.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-cpu-pipeline", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-cpu-pipeline.html", "html": true}')
