   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-alignment', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/instruction/alignment/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-instruction-alignment.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-alignment", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-instruction-alignment.html", "html": true}')
