   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-concepts', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/instruction/concepts/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-instruction-concepts.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-concepts", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-instruction-concepts.html", "html": true}')
