-- 计算机组成原理 / 高级语言和机器码
SET @kp_id := 276;
UPDATE knowledge_point
SET description = '高级语言和机器码 编译过程 💡 低优先级 真题练习 考查得很少，大致了解 编译的具体流程 和 每个阶段的具体任务 就行。 一个传统的 C 程序从源代码到可执行二进制程序的过程中，需要经历 预处理 （Preprocess）、 编译 （Compile）、 汇编 （Assemble）、 链接 （Link）四个步骤，这四个步骤分别由 预处理器 （Preprocessor）、 编译器 （Compiler）、 汇编器 （Assembler）、 链接器 （Linker）完成。 预处理 预处理 （Preprocess）阶段负责对 源代码 （source code）进行文本的转换和处理，将其转化为 扩展代码 （expanded code）。具体而言， 预处理 阶段包含如下工作： 头文件包含 ：将 指令包含的头文件内容插入到源文件中。 宏替换 ：将源代码中定义的宏 进行替换。 删除注释 ：将代码中的注释删除。 编译 编译 （Compile）阶段将 预处理后源代码 （extended code）翻译成 汇编代码 （assembly code）。编译阶段包含 词法分析、', sort_order = COALESCE(sort_order, 48)
WHERE id = 276;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (276, 'knowledge-html/csgraduates/constitution-principle/constitution_principle-instruction-high_low_language.html', '高级语言和机器码 编译过程 💡 低优先级 真题练习 考查得很少，大致了解 编译的具体流程 和 每个阶段的具体任务 就行。 一个传统的 C 程序从源代码到可执行二进制程序的过程中，需要经历 预处理 （Preprocess）、 编译 （Compile）、 汇编 （Assemble）、 链接 （Link）四个步骤，这四个步骤分别由 预处理器 （Preprocessor）、 编译器 （Compiler）、 汇编器 （Assembler）、 链接器 （Linker）完成。 预处理 预处理 （Preprocess）阶段负责对 源代码 （source code）进行文本的转换和处理，将其转化为 扩展代码 （expanded code）。具体而言， 预处理 阶段包含如下工作： 头文件包含 ：将 指令包含的头文件内容插入到源文件中。 宏替换 ：将源代码中定义的宏 进行替换。 删除注释 ：将代码中的注释删除。 编译 编译 （Compile）阶段将 预处理后源代码 （extended code）翻译成 汇编代码 （assembly code）。编译阶段包含 词法分析、', 'https://www.csgraduates.com/constitution_principle/instruction/high_low_language/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-high_low_language', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/instruction/high_low_language/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-instruction-high_low_language.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-high_low_language", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-instruction-high_low_language.html", "html": true}')
