-- 计算机组成原理 / 指令操作码
SET @kp_id := 277;
UPDATE knowledge_point
SET description = '指令操作码 🔥 高优先级 真题练习 本节要和 CPU 中的 控制器 放在一起理解，也是后续 CPU 的基础。当然，其中协处理器和字符串操作指令不大重要，可以不作为重点，其他的操作码都要 深入理解 。 不同计算机架构的指令操作码不相同，但是其中涉及到的功能却大同小异。本节以 x86 平台的指令为例，说明一下指令操作码的主要分类和功能。 数据传输指令 数据传送 数据传送指令 在 x86 中就是 ，将第二个操作数（ 寄存器 的内容、 内存 中的内容或 常数 值）复制到第一个操作数（ 寄存器 或 内存 ），可以实现 寄存器 、 内存 之间的 数据传送 。 栈操作 堆栈 指的是程序的运行栈，从高地址向低地址增长。 指令将 数据 压入栈顶， 指令从栈顶取出 数据 ，并存入 寄存器 或者 内存单元 。 当执行 指令时，需要将 的值 减去数据大小 ，然后将 数据 写入新地址处。 当执行 指令时，需要将栈顶的 数据 （即 处的值）读取到目标 寄存器 或 内存 ，然后将 的值 加上数据大小 ，即弹出 数据 。 下图给出了一个入栈出栈指令的实例，通过 和 指令实现了 ', sort_order = COALESCE(sort_order, 49)
WHERE id = 277;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (277, 'knowledge-html/csgraduates/constitution-principle/constitution_principle-instruction-instruction_ops.html', '指令操作码 🔥 高优先级 真题练习 本节要和 CPU 中的 控制器 放在一起理解，也是后续 CPU 的基础。当然，其中协处理器和字符串操作指令不大重要，可以不作为重点，其他的操作码都要 深入理解 。 不同计算机架构的指令操作码不相同，但是其中涉及到的功能却大同小异。本节以 x86 平台的指令为例，说明一下指令操作码的主要分类和功能。 数据传输指令 数据传送 数据传送指令 在 x86 中就是 ，将第二个操作数（ 寄存器 的内容、 内存 中的内容或 常数 值）复制到第一个操作数（ 寄存器 或 内存 ），可以实现 寄存器 、 内存 之间的 数据传送 。 栈操作 堆栈 指的是程序的运行栈，从高地址向低地址增长。 指令将 数据 压入栈顶， 指令从栈顶取出 数据 ，并存入 寄存器 或者 内存单元 。 当执行 指令时，需要将 的值 减去数据大小 ，然后将 数据 写入新地址处。 当执行 指令时，需要将栈顶的 数据 （即 处的值）读取到目标 寄存器 或 内存 ，然后将 的值 加上数据大小 ，即弹出 数据 。 下图给出了一个入栈出栈指令的实例，通过 和 指令实现了 ', 'https://www.csgraduates.com/constitution_principle/instruction/instruction_ops/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-instruction_ops', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/instruction/instruction_ops/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-instruction-instruction_ops.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-instruction-instruction_ops", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-instruction-instruction_ops.html", "html": true}')
