-- 计算机组成原理 / 计算机性能指标
SET @kp_id := 262;
UPDATE knowledge_point
SET description = '计算机性能指标 🔥 高优先级 真题练习 在选择题中会直接考查，也会在解答题间接考查，每个计算机性能指标都要深入掌握。 CPU 指标 时钟周期 时钟周期 （Clock Cycle）是计算机中 CPU 执行指令的基本时间单位，由系统时钟产生的一个“高低电平”变化（通常称为 脉冲 ）所定义。 计算机内部有一个 晶体振荡器 ，通常采用石英晶体，利用其压电效应产生规律的 脉冲信号 。石英晶体在施加电压时会发生机械振动，而机械振动反过来又会产生电压。通过在电路中合理配置电容和电感元件，晶体振荡器能够在特定频率上持续振荡，形成稳定的机器脉冲源。 原始的脉冲信号 是一个连续的 模拟信号 ，在计算机系统中，这个模拟信号通常不会直接使用。为了适配数字电路的需要， 晶体振荡器 产生的 模拟信号 会经过整形和分频电路处理，转换为方波形式的 数字脉冲信号 ，用于同步计算机中各个硬件组件的操作。 时钟脉冲信号 的宽度，即连续两个 脉冲 之间的时间间隔，称为 时钟周期 。 注意 计算机中所有的设备都使用相同的时钟周期么？ 不一定 。某些组件（如 CPU 和 内存 等）需要同步', sort_order = COALESCE(sort_order, 50)
WHERE id = 262;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (262, 'knowledge-html/csgraduates/constitution-principle/constitution_principle-overview-performance.html', '计算机性能指标 🔥 高优先级 真题练习 在选择题中会直接考查，也会在解答题间接考查，每个计算机性能指标都要深入掌握。 CPU 指标 时钟周期 时钟周期 （Clock Cycle）是计算机中 CPU 执行指令的基本时间单位，由系统时钟产生的一个“高低电平”变化（通常称为 脉冲 ）所定义。 计算机内部有一个 晶体振荡器 ，通常采用石英晶体，利用其压电效应产生规律的 脉冲信号 。石英晶体在施加电压时会发生机械振动，而机械振动反过来又会产生电压。通过在电路中合理配置电容和电感元件，晶体振荡器能够在特定频率上持续振荡，形成稳定的机器脉冲源。 原始的脉冲信号 是一个连续的 模拟信号 ，在计算机系统中，这个模拟信号通常不会直接使用。为了适配数字电路的需要， 晶体振荡器 产生的 模拟信号 会经过整形和分频电路处理，转换为方波形式的 数字脉冲信号 ，用于同步计算机中各个硬件组件的操作。 时钟脉冲信号 的宽度，即连续两个 脉冲 之间的时间间隔，称为 时钟周期 。 注意 计算机中所有的设备都使用相同的时钟周期么？ 不一定 。某些组件（如 CPU 和 内存 等）需要同步', 'https://www.csgraduates.com/constitution_principle/overview/performance/',
   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-overview-performance', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/overview/performance/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-overview-performance.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-overview-performance", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-overview-performance.html", "html": true}')
