  metadata = VALUES(metadata),
  update_time = CURRENT_TIMESTAMP;

-- 计算机组成原理 / 计算机系统层次结构
SET @kp_id := 261;
UPDATE knowledge_point
SET description = '计算机系统层次结构 ⭐ 中优先级 真题练习 选择题中频考点，需要熟悉下 冯诺依曼结构 和 计算机几个层次的语言 。 计算机系统的基本组成 硬件 系统和 软件 系统共同构成了一个完整的计算机系统。硬件指的是有形的物理设备，是计算机系统中实际物理装置的总称。软件指的是在硬件上运行的程序和相关的数据及文档。 硬件 和 软件 关系：硬件是计算机的物理部分，它提供了运行软件所需的基础设施，而软件则是 指令集 ， 指导 硬件如何工作以执行特定的任务。 计算机硬件 冯诺依曼结构 冯·诺依曼提出的 “存储程序” 的思想奠定了当代计算机的基本结构，以此概念为基础的各类计算机通称为 冯·诺依曼机 ，其特点如下： 计算机 硬件 系统由 运算器 、 存储器 、 控制器 、 输入设备 和 输出设备 5 大部件 组成。 指令和数据 以同等地位存储在 存储器 中，形式上没有区别，但计算机应能区分它们。 指令和数据均用 二进制代码 表示，指令包含操作码和地址码，操作码指出操作的类型，地址码指出操作数的地址。 以 运算器 为中心，其他部件配合其工作。 其中 五大部件 的具体功能如', sort_order = COALESCE(sort_order, 51)
WHERE id = 261;
