   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-overview-structure', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/overview/structure/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-overview-structure.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-overview-structure", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-overview-structure.html", "html": true}')
