   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-representation-integer', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/representation/integer/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-representation-integer.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-representation-integer", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-representation-integer.html", "html": true}')
