-- 计算机组成原理 / Cache
SET @kp_id := 272;
UPDATE knowledge_point
SET description = 'Cache 🔥 高优先级 真题练习 这个没必要多说了，408 中绝对的重点，每年都必考而且占分值很多， cache 和 虚拟页式存储器 在 计算机组成原理/操作系统 中的地位就是 耶路撒冷 在西方的地位。 一整章都是重点，映射方式、地址结构、写策略等都务必 深入 掌握。 cache 原理 缓存 是一种临时存储数据的硬件或软件组件，旨在加快后续对该数据的访问速度。当您请求数据时，计算机会先检查 缓存 中是否存在该数据。如果存在（称为 “缓存命中” ，Cache Hit），则可以直接从 缓存 中获取数据，而无需访问内存，从而节省时间和资源。如果 缓存 中不存在该数据（称为 “缓存未命中” ，Cache Miss），则需要从内存获取数据，并将其存储在 缓存 中，以备将来使用。 cache 工作原理 缓存 （cache）是计算机系统中的一种用于加速数据访问的技术，其原理是在高速存储介质中暂时存储常用数据，以便更快地满足后续的访问请求。 缓存 对于程序执行的加速主要来自于 计算机程序 的 时间局部性 （Temperal Locality）和 空间局部性 （', sort_order = COALESCE(sort_order, 56)
WHERE id = 272;
