   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-storage-cache', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/storage/cache/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-storage-cache.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-storage-cache", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-storage-cache.html", "html": true}')
