-- 计算机组成原理 / 内存
SET @kp_id := 270;
UPDATE knowledge_point
SET description = '内存 DRAM 芯片 DRAM 芯片是一种 动态随机存取存储器 ，通过 1T1C （1 晶体管 +1 电容器）存储单元以行列矩阵形式组织数据，依靠电容器电荷存储比特，需定期 刷新 以防止数据丢失。其 高容量、低成本 特性使其广泛用于计算机 主内存 。 刷新方式 💡 低优先级 DRAM 刷新方式简单过一下就行，留个印象，没有直接考察过。 DRAM 的刷新方式包括： 集中刷新 （Burst Refresh），暂停数据访问，在短时间内快速 刷新所有行 ，效率高但延迟大； 分散刷新 （Distributed Refresh），将刷新操作均匀分布在时间段内，与正常访问交错，延迟小但控制复杂； 异步刷新 （Asynchronous Refresh），由外部控制器根据需要触发刷新，灵活但依赖控制器设计。 这些刷新方式的具体对比如下表所示： 特征 集中刷新 分散刷新 异步刷新 刷新方式 所有存储单元同时刷新 根据存储单元的需求刷新 根据使用情况和需求刷新 性能影响 可能导致性能下降，因为刷新操作同时进行 最小程度影响性能，仅刷新需要刷新的存储单元 最小程度影响性', sort_order = COALESCE(sort_order, 58)
WHERE id = 270;
