   'knowledge-assets/csgraduates/constitution-principle/constitution_principle-storage-memory', '{"sourceName": "csgraduates", "subjectName": "计算机组成原理", "sourceUrl": "https://www.csgraduates.com/constitution_principle/storage/memory/", "htmlRef": "knowledge-html/csgraduates/constitution-principle/constitution_principle-storage-memory.html", "assetDir": "knowledge-assets/csgraduates/constitution-principle/constitution_principle-storage-memory", "sourcePath": "knowledge-html-sources/csgraduates/constitution-principle/constitution_principle-storage-memory.html", "html": true}')
