-- 操作系统 / 操作系统概念
SET @kp_id := 289;
UPDATE knowledge_point
SET description = '操作系统概念 💡 低优先级 真题练习 需要了解操作系统的概念，还是经常考一些 基础概念辨析 的选择题的，当然这种题也比较简单。 概念 操作系统 是计算机系统中的一个核心软件组件，负责管理和控制计算机硬件，为用户和应用程序提供服务。 操作系统特征 并发 （Concurrence）： 操作系统 具备同时处理和调度多个程序的能力。 共享 （Sharing）：系统中的资源可供内存中多个并发的进程共同使用。 虚拟 （Virtual）：将物理的实物虚拟为逻辑上的对应物。 异步 （Asynchronism）：任务可以不按固定的顺序执行，因此同一操作的结果可能因执行的时序而异。 目标和功能 作为用户语句计算机硬件系统之间的接口。 作为计算机系统资源的管理者。 实现了对计算机资源的抽象。 发展历程 操作系统 的发展历程经历了 手工操作、批处理操作、分时操作、实时操作 这四个阶段： 手工操作 阶段： 时间背景：计算机的早期阶段。 特点：没有 操作系统 ，用户直接使用计算机硬件。 操作方式：用户在一个时刻将自己的程序载入计算机，然后执行。执行完毕后，将结果记录并释放计', sort_order = COALESCE(sort_order, 67)
WHERE id = 289;
