-- 操作系统 / 操作系统结构
SET @kp_id := 291;
UPDATE knowledge_point
SET description = '操作系统结构 💡 低优先级 真题练习 偶尔在选择题中考一下 宏内核和微内核 以及 虚拟机 的概念。 分层和模块化 操作系统的设计和结构在历史上经历了多种不同的方法和技巧，为了增加 可维护性 、 灵活性 和 可扩展性 。 分层 和 模块化 是操作系统设计中两种主要的技术方法。 分层结构 ： 概念 ：在分层的操作系统中，系统被划分为多个层次或“层”，每层都为其上的层提供服务，并依赖于其下的层。 优点 ： 每层只需与其直接的上下层进行交互，简化了设计和调试。 提高了灵活性，因为改变某一层的实现不会影响到其他层。 有助于保护和安全性，因为较低的层（如硬件访问层）被封装起来，上层代码不能直接访问。 模块化结构 ： 概念 ：模块化操作系统基于模块的概念，每个模块都有一个特定的功能，各个模块之间的交互通过定义良好的接口进行。模块化与面向对象编程中的封装和抽象概念类似。 优点 ： 易于维护和更新。如果某个模块需要更改或修复，可以独立于其他模块进行。 提高了可扩展性。新的功能或模块可以相对容易地添加到系统中。 增加了系统的可靠性和稳定性，因为每个模块的功能都被限定', sort_order = COALESCE(sort_order, 69)
WHERE id = 291;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (291, 'knowledge-html/csgraduates/operating-system/operating_system-concepts-structure.html', '操作系统结构 💡 低优先级 真题练习 偶尔在选择题中考一下 宏内核和微内核 以及 虚拟机 的概念。 分层和模块化 操作系统的设计和结构在历史上经历了多种不同的方法和技巧，为了增加 可维护性 、 灵活性 和 可扩展性 。 分层 和 模块化 是操作系统设计中两种主要的技术方法。 分层结构 ： 概念 ：在分层的操作系统中，系统被划分为多个层次或“层”，每层都为其上的层提供服务，并依赖于其下的层。 优点 ： 每层只需与其直接的上下层进行交互，简化了设计和调试。 提高了灵活性，因为改变某一层的实现不会影响到其他层。 有助于保护和安全性，因为较低的层（如硬件访问层）被封装起来，上层代码不能直接访问。 模块化结构 ： 概念 ：模块化操作系统基于模块的概念，每个模块都有一个特定的功能，各个模块之间的交互通过定义良好的接口进行。模块化与面向对象编程中的封装和抽象概念类似。 优点 ： 易于维护和更新。如果某个模块需要更改或修复，可以独立于其他模块进行。 提高了可扩展性。新的功能或模块可以相对容易地添加到系统中。 增加了系统的可靠性和稳定性，因为每个模块的功能都被限定', 'https://www.csgraduates.com/operating_system/concepts/structure/',
   'knowledge-assets/csgraduates/operating-system/operating_system-concepts-structure', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/concepts/structure/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-concepts-structure.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-concepts-structure", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-concepts-structure.html", "html": true}')
