  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
  asset_dir = VALUES(asset_dir),
  metadata = VALUES(metadata),
  update_time = CURRENT_TIMESTAMP;

-- 操作系统 / 目录
SET @kp_id := 303;
UPDATE knowledge_point
SET description = '目录 ⭐ 中优先级 真题练习 选择题中会考察 目录 以及 硬链接和软链接 的概念。 目录概念 目录是计算机文件系统中用于组织和存储文件和其他目录的一种 重要概念 。目录也被称为文件夹，它是文件系统中的一个 关键组成部分 ，用于创建层次结构，方便用户管理和浏览文件。 树形目录 树形目录是一种 层次化 的文件组织结构，就像一棵倒置的树： 根目录（Root） 是整个目录结构的起点，通常记为 。 根目录 下可以包含多个 子目录 和 文件 ，每个 子目录 下又可以包含更多的目录或文件，以此类推。 每个目录都可以看作是一个 节点 ，通过 路径 连接起来，形成一棵树。 举例目录结构如下（见图）： 示例路径： ：表示在 根目录 下的 子目录 中存在一个名为 的 文件 。 ：表示 文件 位于 目录 下。 这种结构具备以下特点： 层次清晰 ：便于用户查找和管理文件 路径唯一性 ：每个文件或目录都有 唯一的绝对路径 支持相对路径 ：可使用 表示当前目录， 表示上级目录 存储结构 在文件系统中，目录本质上就是一个 特殊类型的文件 ，它的“内容”是一个个 目录项 （dir', sort_order = COALESCE(sort_order, 70)
WHERE id = 303;
