   'knowledge-assets/csgraduates/operating-system/operating_system-files-dir', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/files/dir/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-files-dir.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-files-dir", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-files-dir.html", "html": true}')
