-- 操作系统 / 文件系统
SET @kp_id := 304;
UPDATE knowledge_point
SET description = '文件系统 ⭐ 中优先级 真题练习 本节的重点在于外存空间管理的方法，其他几个知识点也偶有考察，稍微了解下概念就行。 功能 文件系统（ File System ）作为操作系统与存储设备之间的桥梁，负责数据的存储、访问、管理和保护。简单来说，文件系统主要包含以下功能： 数据存储与组织 文件系统以 文件 和 目录 的形式组织数据，将存储设备的物理空间划分为 逻辑单元 （如文件、文件夹），便于用户和应用程序访问与管理数据。 空间管理 通过 空闲块管理 （分配、回收、组织），文件系统高效利用存储空间，减少碎片，支持文件的创建、扩展和删除。常见方法包括 连续分配 、 链接分配 和 索引分配 。 数据访问与操作 提供标准接口（如 读 、 写 、 打开 、 关闭 ）支持对文件的访问和操作，确保数据的高效检索和修改，同时支持 随机访问 和 顺序访问 。 数据保护和安全 权限管理 数据完整性校验 注意 文件系统和磁盘的功能区别 文件系统和磁盘在存储管理中扮演不同角色。磁盘负责物理存储，提供固定大小的 扇区 （通常为 512字节 或 4KB ），作为数据读写的 最小物', sort_order = COALESCE(sort_order, 72)
WHERE id = 304;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
