   'knowledge-assets/csgraduates/operating-system/operating_system-files-file_system', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/files/file_system/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-files-file_system.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-files-file_system", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-files-file_system.html", "html": true}')
