-- 操作系统 / I/O 设备
SET @kp_id := 306;
UPDATE knowledge_point
SET description = 'I/O 设备 💡 低优先级 真题练习 低频考点，对于本节重点掌握 I/O 软件层次的概念，I/O 控制方式的部分建议和计算机组成原理中的 I/O 系统 共同学习。 I/O 接口类型 根据设备类型的不同，我们将 I/O 接口 分为三种类型： 块设备 ： 块设备（Block Device）是计算机中一类以 固定大小的数据块 为单位进行数据读写的 I/O 设备，通常用于存储和检索大量数据。它们 支持随机访问 ，意味着可以直接定位到任意数据块，而无需按顺序读取。 典型例子包括 机械硬盘 （HDD）、 固态硬盘 （SSD）和 USB 闪存盘。 块设备 的 数据传输速率较高 ，但涉及复杂的控制器和协议（如 SATA 或 NVMe)，因此在操作系统中通常由专门的驱动程序管理。 字符设备 ： 字符设备是另一类 I/O 设备，以 连续的字符流 形式进行数据传输，不支持随机访问，也不依赖数据块的概念。它们通常用于与硬件设备交互，如 键盘 、 鼠标 、 串口终端 或 打印机 。字符设备的数据流是顺序的，适合实时或低速数据传输场景。 例如，键盘输入的字符流直接发送到系统', sort_order = COALESCE(sort_order, 73)
WHERE id = 306;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (306, 'knowledge-html/csgraduates/operating-system/operating_system-io_device-devices.html', 'I/O 设备 💡 低优先级 真题练习 低频考点，对于本节重点掌握 I/O 软件层次的概念，I/O 控制方式的部分建议和计算机组成原理中的 I/O 系统 共同学习。 I/O 接口类型 根据设备类型的不同，我们将 I/O 接口 分为三种类型： 块设备 ： 块设备（Block Device）是计算机中一类以 固定大小的数据块 为单位进行数据读写的 I/O 设备，通常用于存储和检索大量数据。它们 支持随机访问 ，意味着可以直接定位到任意数据块，而无需按顺序读取。 典型例子包括 机械硬盘 （HDD）、 固态硬盘 （SSD）和 USB 闪存盘。 块设备 的 数据传输速率较高 ，但涉及复杂的控制器和协议（如 SATA 或 NVMe)，因此在操作系统中通常由专门的驱动程序管理。 字符设备 ： 字符设备是另一类 I/O 设备，以 连续的字符流 形式进行数据传输，不支持随机访问，也不依赖数据块的概念。它们通常用于与硬件设备交互，如 键盘 、 鼠标 、 串口终端 或 打印机 。字符设备的数据流是顺序的，适合实时或低速数据传输场景。 例如，键盘输入的字符流直接发送到系统', 'https://www.csgraduates.com/operating_system/io_device/devices/',
   'knowledge-assets/csgraduates/operating-system/operating_system-io_device-devices', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/io_device/devices/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-io_device-devices.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-io_device-devices", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-io_device-devices.html", "html": true}')
