-- 操作系统 / 磁盘
SET @kp_id := 308;
UPDATE knowledge_point
SET description = '磁盘 磁盘管理 ⭐ 中优先级 真题练习 选择题中考察，重点掌握两点：1. 物理格式化和逻辑格式化的区别 。2. 系统引导流程 。 磁盘初始化 一个新的磁盘只是一个磁性记录材料的空白盘。在磁盘可以存储数据之前，必须对其进行 物理格式化 （也叫做 低级格式化 ）。 物理格式化 是指在磁盘的物理表面上创建 磁道 （track）、 扇区 （sector）、写入控制信息 以及 测试和标记坏扇区等过程。通过这一过程，磁盘被划分为可供读写头访问的物理存储单元，为数据存储和检索提供基础结构。 一般来说，现代硬盘在出厂时已完成 物理格式化 ，并优化了 磁道 和 扇区 的布局。用户通常只需进行 逻辑格式化 即可使用。 分区 在使用磁盘存储文件之前，操作系统首先需要对磁盘进行 分区 ，并且将每个分区的起始扇区和大小都记录在磁盘 主引导记录 （MBR，Master Boot Record）的分区表中。这一过程为磁盘划分出若干 逻辑存储区域 ，每个分区可以独立格式化并使用不同的文件系统，为数据的组织和管理提供了基础。 分区表是存储在磁盘 主引导记录 （MBR）或 GUID', sort_order = COALESCE(sort_order, 74)
WHERE id = 308;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (308, 'knowledge-html/csgraduates/operating-system/operating_system-io_device-disks.html', '磁盘 磁盘管理 ⭐ 中优先级 真题练习 选择题中考察，重点掌握两点：1. 物理格式化和逻辑格式化的区别 。2. 系统引导流程 。 磁盘初始化 一个新的磁盘只是一个磁性记录材料的空白盘。在磁盘可以存储数据之前，必须对其进行 物理格式化 （也叫做 低级格式化 ）。 物理格式化 是指在磁盘的物理表面上创建 磁道 （track）、 扇区 （sector）、写入控制信息 以及 测试和标记坏扇区等过程。通过这一过程，磁盘被划分为可供读写头访问的物理存储单元，为数据存储和检索提供基础结构。 一般来说，现代硬盘在出厂时已完成 物理格式化 ，并优化了 磁道 和 扇区 的布局。用户通常只需进行 逻辑格式化 即可使用。 分区 在使用磁盘存储文件之前，操作系统首先需要对磁盘进行 分区 ，并且将每个分区的起始扇区和大小都记录在磁盘 主引导记录 （MBR，Master Boot Record）的分区表中。这一过程为磁盘划分出若干 逻辑存储区域 ，每个分区可以独立格式化并使用不同的文件系统，为数据的组织和管理提供了基础。 分区表是存储在磁盘 主引导记录 （MBR）或 GUID', 'https://www.csgraduates.com/operating_system/io_device/disks/',
   'knowledge-assets/csgraduates/operating-system/operating_system-io_device-disks', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/io_device/disks/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-io_device-disks.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-io_device-disks", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-io_device-disks.html", "html": true}')
ON DUPLICATE KEY UPDATE
  html_ref = VALUES(html_ref),
  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
  asset_dir = VALUES(asset_dir),
  metadata = VALUES(metadata),
  update_time = CURRENT_TIMESTAMP;

-- 操作系统 / 设备管理
SET @kp_id := 307;
UPDATE knowledge_point
SET description = '设备管理 💡 低优先级 真题练习 低频考点，大致了解下这节的三个概念：缓冲区、设备分配和回收、SPOOLing 就行，在选择题偶尔会考察。 缓冲区 缓冲区 是一块预留在内存中的区域，用于临时存放数据，从而使得输入/输出操作与其他处理操作可以相对独立地进行。 缓冲区 的使用可以减少 I/O 操作的等待时间 ，提高系统的整体效率。 磁盘高速缓存 磁盘缓存 指的是利用内存中的存储空间来暂存从磁盘中读出的一系列盘块中的信息。 因此， 磁盘高速缓存 从逻辑上属于磁盘，物理上则是驻留在内存中的盘块。 缓冲区实现 单缓冲 在 单缓冲 策略中，只有一个 缓冲区 用于数据的读取或写入。 工作过程： 数据从源（例如，磁盘）读入到 单个缓冲区 。 当数据在 缓冲区 内时，应用程序可以从该 缓冲区 中处理数据。 当应用程序处理完 缓冲区 中的数据并需要更多数据时，新的数据再次被读入到同一 缓冲区 中。 缺点：当 缓冲区 被填满并且数据被应用程序处理时， I/O 操作必须等待 ，直到 缓冲区 再次可用。这可能导致 I/O 操作的延迟 。 双缓冲 双缓冲 使用两个 缓冲区 ', sort_order = COALESCE(sort_order, 75)
WHERE id = 307;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
