   'knowledge-assets/csgraduates/operating-system/operating_system-io_device-management', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/io_device/management/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-io_device-management.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-io_device-management", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-io_device-management.html", "html": true}')
