-- 操作系统 / 虚拟内存管理
SET @kp_id := 300;
UPDATE knowledge_point
SET description = '虚拟内存管理 🔥 高优先级 真题练习 页式虚拟存储的细节都在 组成原理章节 ，对于本节，重点掌握 页框分配的几个概念 以及几种 页面置换算法 的细节。 页框分配 在 虚拟内存管理 中， 页框分配 是操作系统为进程分配物理内存（页框）的过程。 它直接影响着系统的性能，因为分配的页框数量会影响进程的 缺页率 和系统的整体吞吐量。 驻留集 驻留集（Resident Set） 是指某个进程在执行过程中，当前实际存放在物理内存中的页面集合。换句话说，它反映了该进程在某一时刻真正占用并可直接访问的物理页。由于进程的地址空间往往远大于物理内存，操作系统通过 虚拟存储管理 来实现“用部分物理内存支撑完整逻辑地址空间”，而驻留集正是这个机制下进程能够被立即访问的 物理页子集 。 驻留集大小（Resident Set Size, RSS） 则是度量该集合规模的指标，通常以页框（page frame）的数量来表示。它决定了进程可直接利用的物理内存范围，从而影响其运行效率。 合理设置驻留集大小对于系统性能至关重要： 过小 ：如果驻留集太小，进程运行时所需的工作集页面无法', sort_order = COALESCE(sort_order, 77)
WHERE id = 300;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (300, 'knowledge-html/csgraduates/operating-system/operating_system-memory-management.html', '虚拟内存管理 🔥 高优先级 真题练习 页式虚拟存储的细节都在 组成原理章节 ，对于本节，重点掌握 页框分配的几个概念 以及几种 页面置换算法 的细节。 页框分配 在 虚拟内存管理 中， 页框分配 是操作系统为进程分配物理内存（页框）的过程。 它直接影响着系统的性能，因为分配的页框数量会影响进程的 缺页率 和系统的整体吞吐量。 驻留集 驻留集（Resident Set） 是指某个进程在执行过程中，当前实际存放在物理内存中的页面集合。换句话说，它反映了该进程在某一时刻真正占用并可直接访问的物理页。由于进程的地址空间往往远大于物理内存，操作系统通过 虚拟存储管理 来实现“用部分物理内存支撑完整逻辑地址空间”，而驻留集正是这个机制下进程能够被立即访问的 物理页子集 。 驻留集大小（Resident Set Size, RSS） 则是度量该集合规模的指标，通常以页框（page frame）的数量来表示。它决定了进程可直接利用的物理内存范围，从而影响其运行效率。 合理设置驻留集大小对于系统性能至关重要： 过小 ：如果驻留集太小，进程运行时所需的工作集页面无法', 'https://www.csgraduates.com/operating_system/memory/management/',
   'knowledge-assets/csgraduates/operating-system/operating_system-memory-management', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/memory/management/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-memory-management.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-memory-management", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-memory-management.html", "html": true}')
