-- 操作系统 / 死锁
SET @kp_id := 297;
UPDATE knowledge_point
SET description = '死锁 ⭐ 中优先级 真题练习 选择题高频考点，本节的几个知识点都经常考察，除了死锁的检测和删除之外。 死锁产生的必要条件 只有以下四个条件同时满足， 死锁 才会发生： 互斥条件 （Mutual Exclusion）: 指的是至少有一个资源必须处于非共享模式，也就是说，一次只有一个进程可以使用资源。如果其他进程请求该资源，那么请求的进程必须等到该资源的持有者释放该资源。 占有并等待 （Hold and Wait）: 指的是一个进程因请求资源而阻塞时，对当前获得的资源保持不放。换句话说，进程至少已经持有一个资源，但又申请新的资源；由于其他进程持有这些资源，所以它现在是阻塞的。 非抢占 （No Preemption）: 资源不能被抢占，也就是说，只有资源的持有者才可以释放它。资源在完全自愿的基础上被释放，不能被强行从持有进程中夺走。 循环等待 （Circular Wait）：存在一个进程资源的等待链，链中的每一个进程都在等待下一个进程所持有的资源。这导致了一个循环的等待链。 为了 避免死锁 ，需要 破坏 上述的任意一个条件。 上图中的进程就处于 死锁状', sort_order = COALESCE(sort_order, 78)
WHERE id = 297;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (297, 'knowledge-html/csgraduates/operating-system/operating_system-process-deadlock.html', '死锁 ⭐ 中优先级 真题练习 选择题高频考点，本节的几个知识点都经常考察，除了死锁的检测和删除之外。 死锁产生的必要条件 只有以下四个条件同时满足， 死锁 才会发生： 互斥条件 （Mutual Exclusion）: 指的是至少有一个资源必须处于非共享模式，也就是说，一次只有一个进程可以使用资源。如果其他进程请求该资源，那么请求的进程必须等到该资源的持有者释放该资源。 占有并等待 （Hold and Wait）: 指的是一个进程因请求资源而阻塞时，对当前获得的资源保持不放。换句话说，进程至少已经持有一个资源，但又申请新的资源；由于其他进程持有这些资源，所以它现在是阻塞的。 非抢占 （No Preemption）: 资源不能被抢占，也就是说，只有资源的持有者才可以释放它。资源在完全自愿的基础上被释放，不能被强行从持有进程中夺走。 循环等待 （Circular Wait）：存在一个进程资源的等待链，链中的每一个进程都在等待下一个进程所持有的资源。这导致了一个循环的等待链。 为了 避免死锁 ，需要 破坏 上述的任意一个条件。 上图中的进程就处于 死锁状', 'https://www.csgraduates.com/operating_system/process/deadlock/',
   'knowledge-assets/csgraduates/operating-system/operating_system-process-deadlock', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/process/deadlock/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-process-deadlock.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-process-deadlock", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-process-deadlock.html", "html": true}')
