-- 操作系统 / 经典同步问题
SET @kp_id := 296;
UPDATE knowledge_point
SET description = '经典同步问题 🔥 高优先级 真题练习 同步问题设计 是操作系统解答题必考题，本节的几个经典问题虽然不会直接考察，但是其中的设计思想还是需要深入掌握。 生产者消费者问题 生产者消费者问题是并发编程中的经典问题，涉及到两种线程 —— 生产者 和 消费者 ，它们共享一个固定大小的缓冲区或存储区。 生产者的任务是生成数据并将其 放入缓冲区 。 消费者的任务是 从缓冲区中取出 并消费这些数据。 关键的挑战在于确保生产者不会在缓冲区满时添加数据，同时确保消费者不会在缓冲区空时尝试消费数据。 生产者消费者过程可以参考以下流程图理解： 读者 - 写者问题 读者写者问题 是另一个经典的并发编程问题，涉及到对 共享数据 或 资源 的访问，这些 资源 可以被 多个读者 同时读取，但只能被 一个写者 写入，而且当 写者 正在写入数据时，没有其他 读者 或 写者 可以访问该 资源 。 这个问题的挑战在于两点： 允许多个读者同时读取资源。 确保当有一个写者访问资源时，没有其他读者或写者可以同时访问。 试题中如果考察读者写者问题的话，一般考察的还是读者优先，读者优先的同步实现', sort_order = COALESCE(sort_order, 79)
WHERE id = 296;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (296, 'knowledge-html/csgraduates/operating-system/operating_system-process-problem.html', '经典同步问题 🔥 高优先级 真题练习 同步问题设计 是操作系统解答题必考题，本节的几个经典问题虽然不会直接考察，但是其中的设计思想还是需要深入掌握。 生产者消费者问题 生产者消费者问题是并发编程中的经典问题，涉及到两种线程 —— 生产者 和 消费者 ，它们共享一个固定大小的缓冲区或存储区。 生产者的任务是生成数据并将其 放入缓冲区 。 消费者的任务是 从缓冲区中取出 并消费这些数据。 关键的挑战在于确保生产者不会在缓冲区满时添加数据，同时确保消费者不会在缓冲区空时尝试消费数据。 生产者消费者过程可以参考以下流程图理解： 读者 - 写者问题 读者写者问题 是另一个经典的并发编程问题，涉及到对 共享数据 或 资源 的访问，这些 资源 可以被 多个读者 同时读取，但只能被 一个写者 写入，而且当 写者 正在写入数据时，没有其他 读者 或 写者 可以访问该 资源 。 这个问题的挑战在于两点： 允许多个读者同时读取资源。 确保当有一个写者访问资源时，没有其他读者或写者可以同时访问。 试题中如果考察读者写者问题的话，一般考察的还是读者优先，读者优先的同步实现', 'https://www.csgraduates.com/operating_system/process/problem/',
   'knowledge-assets/csgraduates/operating-system/operating_system-process-problem', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/process/problem/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-process-problem.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-process-problem", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-process-problem.html", "html": true}')
ON DUPLICATE KEY UPDATE
  html_ref = VALUES(html_ref),
  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
  asset_dir = VALUES(asset_dir),
  metadata = VALUES(metadata),
  update_time = CURRENT_TIMESTAMP;

-- 操作系统 / 进程和线程
SET @kp_id := 293;
UPDATE knowledge_point
SET description = '进程和线程 进程和线程 🔥 高优先级 真题练习 进程的相关概念 是历年操作系统选择题必考，关键在于几点：进程和线程、进程状态转换、进程内存空间的架构。 在多道程序环境下，允许多个程序并发执行，为此操作系统引入了 进程 (Process) 的概念，以便更好地描述和控制程序的并发执行，实现操作系统的并发性。 进程 进程是系统资源分配的基本单位 。进程拥有独立的系统资源，包括内存空间、文件描述符、CPU 时间片等，这些资源的分配由操作系统负责。 进程和程序 程序是 静态的 ，进程是 动态的 ，进程可以理解成运行的程序，两者的具体区别如下： 程序 程序是一组指令的静态集合，它存储在磁盘等持久性存储介质中。 程序是被动的，它本身并不执行任何操作。 一个程序可以多次运行，每次运行都会创建一个新的进程。 进程 进程是程序在内存中执行的实例。 当一个程序被加载到内存中并开始执行时，操作系统会创建一个进程。 进程是动态的，它代表了程序的执行过程。 进程控制块 操作系统通过 进程控制块 （PCB，Process Control Block）对进程进行管理。 PCB ', sort_order = COALESCE(sort_order, 80)
WHERE id = 293;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (293, 'knowledge-html/csgraduates/operating-system/operating_system-process-process_thread.html', '进程和线程 进程和线程 🔥 高优先级 真题练习 进程的相关概念 是历年操作系统选择题必考，关键在于几点：进程和线程、进程状态转换、进程内存空间的架构。 在多道程序环境下，允许多个程序并发执行，为此操作系统引入了 进程 (Process) 的概念，以便更好地描述和控制程序的并发执行，实现操作系统的并发性。 进程 进程是系统资源分配的基本单位 。进程拥有独立的系统资源，包括内存空间、文件描述符、CPU 时间片等，这些资源的分配由操作系统负责。 进程和程序 程序是 静态的 ，进程是 动态的 ，进程可以理解成运行的程序，两者的具体区别如下： 程序 程序是一组指令的静态集合，它存储在磁盘等持久性存储介质中。 程序是被动的，它本身并不执行任何操作。 一个程序可以多次运行，每次运行都会创建一个新的进程。 进程 进程是程序在内存中执行的实例。 当一个程序被加载到内存中并开始执行时，操作系统会创建一个进程。 进程是动态的，它代表了程序的执行过程。 进程控制块 操作系统通过 进程控制块 （PCB，Process Control Block）对进程进行管理。 PCB ', 'https://www.csgraduates.com/operating_system/process/process_thread/',
   'knowledge-assets/csgraduates/operating-system/operating_system-process-process_thread', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/process/process_thread/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-process-process_thread.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-process-process_thread", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-process-process_thread.html", "html": true}')
