-- 操作系统 / 处理机调度
SET @kp_id := 294;
UPDATE knowledge_point
SET description = '处理机调度 🔥 高优先级 真题练习 选择题必考内容，重点掌握 调度指标的计算 和 各种调度算法的实现细节 ，调度的实现 和 进程上下文切换相比之下考察比较少。 调度指标 在操作系统里， 调度 （Scheduling） 是把 CPU 时间合理分配给多个进程（或线程）的核心机制。调度的好坏直接决定系统的响应速度、吞吐能力以及资源利用效率。为了衡量调度策略的优劣，我们通常用一组 调度指标 来量化： 系统层面的宏观指标 ——关注整个计算机系统的运行状态，如 CPU 的利用率、系统整体的吞吐量等。这类指标帮助我们了解系统在整体负载下是否“忙碌”或出现瓶颈。 进程层面的微观指标 ——关注单个进程在调度器眼中的表现，包括它何时进入调度队列、等待多久才被分配 CPU、实际执行多长时间以及最终何时完成等。这类指标可以帮助我们比较不同调度算法（FCFS、SJF、RR、优先级调度等）对单个作业的影响。 系统层面 系统层面主要关注 CPU 利用率和吞吐量这两个指标： 系统指标 含义 CPU 利用率 CPU 活跃时间与总观察时间的比率。通常表示为百分比 系统吞吐量 操作系', sort_order = COALESCE(sort_order, 81)
WHERE id = 294;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (294, 'knowledge-html/csgraduates/operating-system/operating_system-process-scheduling.html', '处理机调度 🔥 高优先级 真题练习 选择题必考内容，重点掌握 调度指标的计算 和 各种调度算法的实现细节 ，调度的实现 和 进程上下文切换相比之下考察比较少。 调度指标 在操作系统里， 调度 （Scheduling） 是把 CPU 时间合理分配给多个进程（或线程）的核心机制。调度的好坏直接决定系统的响应速度、吞吐能力以及资源利用效率。为了衡量调度策略的优劣，我们通常用一组 调度指标 来量化： 系统层面的宏观指标 ——关注整个计算机系统的运行状态，如 CPU 的利用率、系统整体的吞吐量等。这类指标帮助我们了解系统在整体负载下是否“忙碌”或出现瓶颈。 进程层面的微观指标 ——关注单个进程在调度器眼中的表现，包括它何时进入调度队列、等待多久才被分配 CPU、实际执行多长时间以及最终何时完成等。这类指标可以帮助我们比较不同调度算法（FCFS、SJF、RR、优先级调度等）对单个作业的影响。 系统层面 系统层面主要关注 CPU 利用率和吞吐量这两个指标： 系统指标 含义 CPU 利用率 CPU 活跃时间与总观察时间的比率。通常表示为百分比 系统吞吐量 操作系', 'https://www.csgraduates.com/operating_system/process/scheduling/',
   'knowledge-assets/csgraduates/operating-system/operating_system-process-scheduling', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/process/scheduling/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-process-scheduling.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-process-scheduling", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-process-scheduling.html", "html": true}')
