-- 操作系统 / 同步和互斥
SET @kp_id := 295;
UPDATE knowledge_point
SET description = '同步和互斥 🔥 高优先级 同步和互斥是 解答题同步问题设计 的基础，也是每年必考点，重要性这里就不多赘述了，这一节的每个知识点的细节都要深入掌握。 临界区和互斥 在并发编程中， 临界区 （Critical Section）是指一个程序中仅允许 一个线程 或 进程 访问的代码片段。这些代码通常会访问 共享资源 ，比如内存、文件、数据库等。当多个线程或进程试图同时访问这些共享资源时，可能会导致数据不一致或其他并发问题。因此，需要一种机制来确保在任何时候，保证在 一个时刻只有一个线程或进程 能够访问 临界区 的代码。 这种机制就叫做 互斥 ： 互斥 （Mutual Exclusion）是计算机科学中一种用于防止多个进程或线程同时访问共享资源或 临界区 的机制。其主要目标是避免资源竞争和数据不一致的问题。 互斥 保证在任何时刻，最多只有 一个线程或进程 可以访问特定的共享资源，从而确保数据的完整性。 临界资源 临界资源 就是 共享资源 ，共享资源可以被多个 线程/进程 同时访问。 比如一个进程的 全局变量 可以被该进程内的多个 线程 同时访问，这个全局变', sort_order = COALESCE(sort_order, 82)
WHERE id = 295;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (295, 'knowledge-html/csgraduates/operating-system/operating_system-process-sync.html', '同步和互斥 🔥 高优先级 同步和互斥是 解答题同步问题设计 的基础，也是每年必考点，重要性这里就不多赘述了，这一节的每个知识点的细节都要深入掌握。 临界区和互斥 在并发编程中， 临界区 （Critical Section）是指一个程序中仅允许 一个线程 或 进程 访问的代码片段。这些代码通常会访问 共享资源 ，比如内存、文件、数据库等。当多个线程或进程试图同时访问这些共享资源时，可能会导致数据不一致或其他并发问题。因此，需要一种机制来确保在任何时候，保证在 一个时刻只有一个线程或进程 能够访问 临界区 的代码。 这种机制就叫做 互斥 ： 互斥 （Mutual Exclusion）是计算机科学中一种用于防止多个进程或线程同时访问共享资源或 临界区 的机制。其主要目标是避免资源竞争和数据不一致的问题。 互斥 保证在任何时刻，最多只有 一个线程或进程 可以访问特定的共享资源，从而确保数据的完整性。 临界资源 临界资源 就是 共享资源 ，共享资源可以被多个 线程/进程 同时访问。 比如一个进程的 全局变量 可以被该进程内的多个 线程 同时访问，这个全局变', 'https://www.csgraduates.com/operating_system/process/sync/',
   'knowledge-assets/csgraduates/operating-system/operating_system-process-sync', '{"sourceName": "csgraduates", "subjectName": "操作系统", "sourceUrl": "https://www.csgraduates.com/operating_system/process/sync/", "htmlRef": "knowledge-html/csgraduates/operating-system/operating_system-process-sync.html", "assetDir": "knowledge-assets/csgraduates/operating-system/operating_system-process-sync", "sourcePath": "knowledge-html-sources/csgraduates/operating-system/operating_system-process-sync.html", "html": true}')
