SET @kp_id := 319;
UPDATE knowledge_point
SET description = '数据链路层 在选择题中考察，个别年份也在大题中考察过，需熟练掌握介质访问控制的相关方法。 学习思维导图： 数据链路层功能 封装数据帧（Frame Encapsulation）： 数据链路层将来自网络层的数据包封装成数据帧，这包括将源和目标地址添加到帧头部，以便在物理介质上的传输。 数据帧传输（Frame Transmission）： 数据链路层负责将数据帧从一个物理节点传输到另一个物理节点。这可能涉及到点对点的传输（例如，以太网）或多点广播传输（例如，Wi-Fi）。 物理地址寻址（Physical Addressing）： 数据链路层使用物理地址（通常是 MAC 地址）来标识设备。这些地址用于确定数据帧的目标设备。 帧同步和定界（Frame Synchronization and Framing）： 数据链路层确保接收端可以正确识别和分离不同的数据帧。这通常通过在帧的起始和结束位置使用特殊的比特模式来实现。 流量控制（Flow Control）： 数据链路层可以控制发送端的数据传输速率，以防止接收端不堪重负而丢失数据。这确保了适当的数据流量管理。', sort_order = COALESCE(sort_order, 85)
WHERE id = 319;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (319, 'knowledge-html/csgraduates/computer-network/computer_network-datalink.html', '数据链路层 在选择题中考察，个别年份也在大题中考察过，需熟练掌握介质访问控制的相关方法。 学习思维导图： 数据链路层功能 封装数据帧（Frame Encapsulation）： 数据链路层将来自网络层的数据包封装成数据帧，这包括将源和目标地址添加到帧头部，以便在物理介质上的传输。 数据帧传输（Frame Transmission）： 数据链路层负责将数据帧从一个物理节点传输到另一个物理节点。这可能涉及到点对点的传输（例如，以太网）或多点广播传输（例如，Wi-Fi）。 物理地址寻址（Physical Addressing）： 数据链路层使用物理地址（通常是 MAC 地址）来标识设备。这些地址用于确定数据帧的目标设备。 帧同步和定界（Frame Synchronization and Framing）： 数据链路层确保接收端可以正确识别和分离不同的数据帧。这通常通过在帧的起始和结束位置使用特殊的比特模式来实现。 流量控制（Flow Control）： 数据链路层可以控制发送端的数据传输速率，以防止接收端不堪重负而丢失数据。这确保了适当的数据流量管理。', 'https://www.csgraduates.com/computer_network/datalink/',
   'knowledge-assets/csgraduates/computer-network/computer_network-datalink', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink.html", "html": true}')
