-- 计算机网络 / 传输层
SET @kp_id := 334;
UPDATE knowledge_point
SET description = '传输层 本章是计算机网络中的重点，需熟练掌握 TCP 的滑动窗口机制、连接断开与建立、流量和拥塞控制。 学习思维导图 传输层功能 数据分段与重组：传输层将上层应用层提供的数据流划分为较小的数据段，以便在网络中传输。在接收端，传输层负责将这些数据段重新组装成完整的数据流，以交付给应用层。 端口标识与多路复用：传输层使用端口号来标识不同的应用程序或服务。当多个应用程序同时运行时，传输层可以将它们的数据段混合在一起传输，并在接收端根据端口号将数据分发给正确的应用程序，从而实现多路复用。 会话管理：传输层还可以支持会话管理，包括建立、维护和终止与远程主机之间的通信会话。这是通过传输层协议中的握手和挥手过程来实现的，例如 TCP 握手过程。 差错检测与纠正：传输层可以检测并纠正数据传输过程中的错误，确保数据的完整性和正确性。这通常涉及使用校验和和纠错码等技术。 TCP UDP', sort_order = COALESCE(sort_order, 89)
WHERE id = 334;
