   'knowledge-assets/csgraduates/computer-network/computer_network-transport', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/transport/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-transport.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-transport", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-transport.html", "html": true}')
