-- 计算机网络 / DNS
SET @kp_id := 339;
UPDATE knowledge_point
SET description = 'DNS 💡 低优先级 真题练习 在选择题中偶尔有考查，需要掌握 DNS 的域名服务器的不同层级，以及域名解析过程的两种方式（迭代和递归）。 层次域名空间 DNS 使用 层次域名空间 来组织域名，将域名划分为多个级别，每个级别之间以点（.）分隔。域名从右到左逐级递增，最右边是 顶级域名 （TLD），然后是 二级域名 ， 三级域名 ，以此类推。 例如， 中， 是顶级域名， 是二级域名， 是子域名。 DNS 层次域名空间 的设计使得域名分布在不同的管理区域中，每个管理区域负责管理其自己的域名空间。这种分层结构有助于提高可扩展性和效率。 域名服务器 在 DNS 体系结构中，服务器按照层级划分，每一层负责不同的职责。下面按照从最高层到最低层的顺序，对四类常见的域名服务器进行说明： 根域名服务器 ( Root Name Servers ): 这些服务器位于 DNS 解析的最顶端。它们不直接回答关于哪个域名映射到哪个 IP 地址的查询，而是告诉查询者下一步应该询问哪个顶级域名（TLD）服务器。 根服务器的数量是有限的，并且它们的位置在全球都是已知的。 顶级域名', sort_order = COALESCE(sort_order, 90)
WHERE id = 339;
