   'knowledge-assets/csgraduates/computer-network/computer_network-application-dns', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/application/dns/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-application-dns.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-application-dns", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-application-dns.html", "html": true}')
