-- 计算机网络 / FTP
SET @kp_id := 340;
UPDATE knowledge_point
SET description = 'FTP 💡 低优先级 真题练习 考查概率比较小，了解 FTP 的基本原理，以及 数据连接 和 控制连接 的功能即可。 工作原理 FTP 的传输流程如下： 建立连接 FTP 基于 TCP 协议 运行。客户端与服务器之间首先建立一条 控制连接 （默认端口 21），用于命令与响应的传输。 在实际传输数据时，还需要建立一条 数据连接 。 身份验证 建立控制连接后，客户端需提供用户名和密码完成身份验证。 部分服务器支持 匿名 FTP ，允许用户以通用用户名（通常为 ）和邮箱地址作为密码进行访问。 命令与响应 所有的 命令与响应 都通过控制连接完成。 客户端发送命令（如上传、下载、列目录等），服务器返回 状态码 （如成功、失败、权限不足），用于指示执行结果。 数据连接的建立 当需要传输文件或目录列表时，FTP 会额外建立数据连接。 常见的两种模式： 主动模式 （Active Mode）：客户端开放端口，等待服务器回连进行数据传输。 被动模式 （Passive Mode）：服务器开放端口，等待客户端发起连接。 文件传输 数据连接建立后即可传输数据，包括文件内容', sort_order = COALESCE(sort_order, 91)
WHERE id = 340;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (340, 'knowledge-html/csgraduates/computer-network/computer_network-application-ftp.html', 'FTP 💡 低优先级 真题练习 考查概率比较小，了解 FTP 的基本原理，以及 数据连接 和 控制连接 的功能即可。 工作原理 FTP 的传输流程如下： 建立连接 FTP 基于 TCP 协议 运行。客户端与服务器之间首先建立一条 控制连接 （默认端口 21），用于命令与响应的传输。 在实际传输数据时，还需要建立一条 数据连接 。 身份验证 建立控制连接后，客户端需提供用户名和密码完成身份验证。 部分服务器支持 匿名 FTP ，允许用户以通用用户名（通常为 ）和邮箱地址作为密码进行访问。 命令与响应 所有的 命令与响应 都通过控制连接完成。 客户端发送命令（如上传、下载、列目录等），服务器返回 状态码 （如成功、失败、权限不足），用于指示执行结果。 数据连接的建立 当需要传输文件或目录列表时，FTP 会额外建立数据连接。 常见的两种模式： 主动模式 （Active Mode）：客户端开放端口，等待服务器回连进行数据传输。 被动模式 （Passive Mode）：服务器开放端口，等待客户端发起连接。 文件传输 数据连接建立后即可传输数据，包括文件内容', 'https://www.csgraduates.com/computer_network/application/ftp/',
   'knowledge-assets/csgraduates/computer-network/computer_network-application-ftp', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/application/ftp/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-application-ftp.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-application-ftp", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-application-ftp.html", "html": true}')
ON DUPLICATE KEY UPDATE
  html_ref = VALUES(html_ref),
  summary_text = VALUES(summary_text),
  source_url = VALUES(source_url),
  asset_dir = VALUES(asset_dir),
  metadata = VALUES(metadata),
