-- 计算机网络 / 电子邮件
SET @kp_id := 341;
UPDATE knowledge_point
SET description = '电子邮件 ⭐ 中优先级 真题练习 在选择题中考查，主要关注 SMTP、POP3、MIME 这几个协议的特点，还需要了解下电子邮件系统中几个组成部分。 电子邮件系统 电子邮件系统由 用户代理 、 邮件服务器 以及 电子邮件协议 这三个核心组成部分协同工作，确保邮件的发送、接收和存储。 用户代理 用户代理 （UA, User Agent）是用户与电子邮件系统交互的接口，通常是邮件客户端软件（如 qq 邮箱网页界面、Outlook 等）。 功能： 提供用户友好的界面，用于撰写、发送、接收和阅读邮件。 管理邮件文件夹（如收件箱、已发送、草稿）。 与邮件服务器通信以发送或获取邮件。 邮件服务器 邮件服务器 （Mail Server）是电子邮件系统的核心，负责存储、转发和管理邮件。 功能： 接收来自用户代理的邮件并存储。 根据邮件的目标地址，通过 SMTP 协议将邮件转发到目标邮件服务器。 提供邮件存储功能，供用户通过 POP3 /IMAP 协议访问。 SMTP SMTP （Simple Mail Transfer Protocol）是用于邮件发送的标准协议', sort_order = COALESCE(sort_order, 92)
WHERE id = 341;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
