-- 计算机网络 / 网络应用模型
SET @kp_id := 338;
UPDATE knowledge_point
SET description = '网络应用模型 💡 低优先级 真题练习 非常简单的两个概念，简单看看，基本就是常识，选择题有小概率考查，都是送分题。 C/S 模型 C/S（Client Server）模型：中心化、依赖服务器，适合稳定服务场景。 核心特点： 客户端 （用户设备，如电脑、手机）向 服务器 （提供服务的专用设备）请求资源或服务，服务器响应并提供支持。 通信方式：基于 “请求-响应” ，客户端主动发起，服务器被动应答。 架构： 中心化 ，服务器是核心枢纽，客户端依赖服务器获取服务。 典型例子 ：浏览网页（浏览器与 Web 服务器）、收发邮件（邮件客户端与邮件服务器）。 P2P 模型 P2P（Peer to Peer）：分布式、节点平等，适合资源共享和去中心化场景。 核心特点：网络中 设备对等 ，既是客户端又可作服务器，共同协作共享资源。 通信方式：设备直接互联， 点对点通信 ，无需中心服务器。 架构： 分布式，去中心化 ，资源分散在各节点，网络更灵活。 典型例子 ：文件共享（如 BitTorrent）、音视频通话（如 Skype）、区块链（如比特币）。', sort_order = COALESCE(sort_order, 93)
WHERE id = 338;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
