-- 计算机网络 / 万维网
SET @kp_id := 342;
UPDATE knowledge_point
SET description = '万维网 ⭐ 中优先级 真题练习 经常在选择题中考查 HTTP 协议的几个特性，包含 HTTP 的基本方法和状态码以及几个关键字段。 WWW WWW ，也称为 万维网 （World Wide Web），是一个信息系统，在这个系统中，文档和其他资源通过 统一资源标识符 （Uniform Resource Identifiers，或 URI ，通常为 URL ）进行标识和互相链接。用户可以使用 网络浏览器 访问 万维网 上的资源。 组成结构 URL (统一资源定位符)：每个网页或资源都有一个唯一的地址，称为 URL ，它定义了资源的位置和如何访问它。 HTTP/HTTPS (超文本传输协议/安全超文本传输协议)：这是用于从服务器传输网页到浏览器的协议。 HTML (超文本标记语言)：大多数网页使用 HTML 编写，它是用于描述和呈现超文本的标准标记语言。 HTTP 协议 HTTP （超文本传输协议） 是互联网上应用最为广泛的一种网络协议 。它是一个属于 应用层 的协议，常基于 TCP/IP 协议通信。 HTTP 用于 客户端 和 服务器 之间的数据传输', sort_order = COALESCE(sort_order, 94)
WHERE id = 342;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (342, 'knowledge-html/csgraduates/computer-network/computer_network-application-www.html', '万维网 ⭐ 中优先级 真题练习 经常在选择题中考查 HTTP 协议的几个特性，包含 HTTP 的基本方法和状态码以及几个关键字段。 WWW WWW ，也称为 万维网 （World Wide Web），是一个信息系统，在这个系统中，文档和其他资源通过 统一资源标识符 （Uniform Resource Identifiers，或 URI ，通常为 URL ）进行标识和互相链接。用户可以使用 网络浏览器 访问 万维网 上的资源。 组成结构 URL (统一资源定位符)：每个网页或资源都有一个唯一的地址，称为 URL ，它定义了资源的位置和如何访问它。 HTTP/HTTPS (超文本传输协议/安全超文本传输协议)：这是用于从服务器传输网页到浏览器的协议。 HTML (超文本标记语言)：大多数网页使用 HTML 编写，它是用于描述和呈现超文本的标准标记语言。 HTTP 协议 HTTP （超文本传输协议） 是互联网上应用最为广泛的一种网络协议 。它是一个属于 应用层 的协议，常基于 TCP/IP 协议通信。 HTTP 用于 客户端 和 服务器 之间的数据传输', 'https://www.csgraduates.com/computer_network/application/www/',
   'knowledge-assets/csgraduates/computer-network/computer_network-application-www', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/application/www/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-application-www.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-application-www", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-application-www.html", "html": true}')
