-- 计算机网络 / 数据链路层设备
SET @kp_id := 325;
UPDATE knowledge_point
SET description = '数据链路层设备 ⭐ 中优先级 真题练习 需要了解三点：转发表结构、交换机转发流程 以及 交换方式，选择题会考查，也作为解答题的基础。 交换机 交换机（Switch）是网络中用于连接设备并转发数据帧的二层设备。它通过分析数据帧中的 MAC 地址，将数据帧从接收端口精准转发到 目标设备所在的端口 。相比 集线器 ，交换机只将数据帧发送到必要端口，避免广播到整个网络， 显著降低碰撞域 ，提升带宽利用率和传输速度。 转发表 转发表（也称 MAC 地址表 ）是交换机内部维护的一张记录表，存储了网络设备 MAC 地址 与其 连接端口 的对应关系。每条记录通常包含以下信息： MAC 地址 ：网络设备的唯一标识。 端口号 ：设备连接的交换机端口。 附加信息 （可选）：如 VLAN 标识或条目有效时间。 如上图所示，交换机 A 和 B 分别通过 转发表 记录了通往每个 MAC 地址 的端口。 转发流程 当交换机收到数据帧后，会根据 转发表（MAC 地址表） 执行以下步骤： 检查目标 MAC 地址 从数据帧的头部提取目标 MAC 地址。 查询转发表（MAC 地址表）', sort_order = COALESCE(sort_order, 95)
WHERE id = 325;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (325, 'knowledge-html/csgraduates/computer-network/computer_network-datalink-dev.html', '数据链路层设备 ⭐ 中优先级 真题练习 需要了解三点：转发表结构、交换机转发流程 以及 交换方式，选择题会考查，也作为解答题的基础。 交换机 交换机（Switch）是网络中用于连接设备并转发数据帧的二层设备。它通过分析数据帧中的 MAC 地址，将数据帧从接收端口精准转发到 目标设备所在的端口 。相比 集线器 ，交换机只将数据帧发送到必要端口，避免广播到整个网络， 显著降低碰撞域 ，提升带宽利用率和传输速度。 转发表 转发表（也称 MAC 地址表 ）是交换机内部维护的一张记录表，存储了网络设备 MAC 地址 与其 连接端口 的对应关系。每条记录通常包含以下信息： MAC 地址 ：网络设备的唯一标识。 端口号 ：设备连接的交换机端口。 附加信息 （可选）：如 VLAN 标识或条目有效时间。 如上图所示，交换机 A 和 B 分别通过 转发表 记录了通往每个 MAC 地址 的端口。 转发流程 当交换机收到数据帧后，会根据 转发表（MAC 地址表） 执行以下步骤： 检查目标 MAC 地址 从数据帧的头部提取目标 MAC 地址。 查询转发表（MAC 地址表）', 'https://www.csgraduates.com/computer_network/datalink/dev/',
   'knowledge-assets/csgraduates/computer-network/computer_network-datalink-dev', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/dev/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink-dev.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink-dev", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink-dev.html", "html": true}')
