-- 计算机网络 / 差错控制
SET @kp_id := 321;
UPDATE knowledge_point
SET description = '差错控制 💡 低优先级 真题练习 说实话本节细节极多但是考查频率很低，考的话一般是在选择题考一题，这一节的几个知识点说实话只能硬背了，大家可以根据自身精力决定要不要搏一搏这可能出现的两分。 分类 检错编码 ：奇偶校验码、循环冗余码 纠错编码 ：海明码 奇偶校验码 奇偶校验码（Parity Check Code）是一种 简单高效 的错误检测机制，广泛应用于数据传输和存储系统中，用于发现 单比特错误 。其核心思想是通过添加一个 校验比特 （parity bit），确保数据中“1”的总数符合特定的奇偶规则。 奇偶校验码有两种常见的类型： 奇校验 和 偶校验 。 奇校验 （Odd Parity）： 校验比特的值使数据（包括校验比特）中“1”的总数为 奇数 。 例如，若原始数据“1”的个数为 偶数 ，校验比特设为 1 ；若为 奇数 ，设为 0 。 若接收端检测到“1”的总数为 偶数 ，则说明传输中存在错误。 偶校验 （Even Parity）： 校验比特确保数据中“1”的总数为 偶数 。 例如，若原始数据“1”的个数为 奇数 ，校验比特设为 1 ；若为 偶', sort_order = COALESCE(sort_order, 96)
WHERE id = 321;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (321, 'knowledge-html/csgraduates/computer-network/computer_network-datalink-error.html', '差错控制 💡 低优先级 真题练习 说实话本节细节极多但是考查频率很低，考的话一般是在选择题考一题，这一节的几个知识点说实话只能硬背了，大家可以根据自身精力决定要不要搏一搏这可能出现的两分。 分类 检错编码 ：奇偶校验码、循环冗余码 纠错编码 ：海明码 奇偶校验码 奇偶校验码（Parity Check Code）是一种 简单高效 的错误检测机制，广泛应用于数据传输和存储系统中，用于发现 单比特错误 。其核心思想是通过添加一个 校验比特 （parity bit），确保数据中“1”的总数符合特定的奇偶规则。 奇偶校验码有两种常见的类型： 奇校验 和 偶校验 。 奇校验 （Odd Parity）： 校验比特的值使数据（包括校验比特）中“1”的总数为 奇数 。 例如，若原始数据“1”的个数为 偶数 ，校验比特设为 1 ；若为 奇数 ，设为 0 。 若接收端检测到“1”的总数为 偶数 ，则说明传输中存在错误。 偶校验 （Even Parity）： 校验比特确保数据中“1”的总数为 偶数 。 例如，若原始数据“1”的个数为 奇数 ，校验比特设为 1 ；若为 偶', 'https://www.csgraduates.com/computer_network/datalink/error/',
   'knowledge-assets/csgraduates/computer-network/computer_network-datalink-error', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/error/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink-error.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink-error", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink-error.html", "html": true}')
