-- 计算机网络 / 流量控制
SET @kp_id := 322;
UPDATE knowledge_point
SET description = '流量控制 🔥 高优先级 真题练习 选择题和解答题都经常考查 ARQ 协议，三个重点不能忽略：1. 三种 ARQ 协议的 实现原理 。 2. 窗口大小的限制 。3. 信道利用率 的计算方法。 这一节都是理解性内容，需要理清背后的原理。 ARQ 协议 ARQ 协议是一类 可靠数据传输协议 ，用于在 不可靠的信道 （比如可能出错或丢包的网络链路）上实现 可靠通信 。 ARQ 协议的 核心思想 是： 发送方在发送数据后，必须等待接收方的确认（ACK）。 如果在规定时间内没有收到确认，就认为数据丢失或出错，需要重传。 ARQ 协议主要包括三种形式： 停等 （Stop‑and‑Wait）、 回退 N 帧 （Go‑Back‑N）以及 选择性重传 （Selective Repeat）。其中，回退 N 帧和选择性重传统称为 连续 ARQ 协议 。 注意 ARQ 在哪一层使用 考研模型里默认： 链路层：可能用 ARQ（作为差错控制手段之一），适用于误码率较高的链路 以太网不使用 无线链路、卫星通信会用 传输层：一定用 ARQ（TCP） 但要记住一句本质话： ARQ ', sort_order = COALESCE(sort_order, 97)
WHERE id = 322;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
