   'knowledge-assets/csgraduates/computer-network/computer_network-datalink-flow_control', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/flow_control/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink-flow_control.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink-flow_control", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink-flow_control.html", "html": true}')
