-- 计算机网络 / 组帧
SET @kp_id := 320;
UPDATE knowledge_point
SET description = '组帧 💡 低优先级 较少考查，了解下几种组帧方法的原理即可。 数据链路层的主要功能之一就是 组帧 。 帧（frame）代表数据链路层的数据发送单位，在接收到来自于网络层的报文（packet）时如何为其添加帧头和帧尾，并且以何种方式进行 帧定界 （接收方区别连续不同的帧）。 组帧 的关键就在于 帧定界 ，也就是对于接收方来说，它能够以某种方式区分连续收到的不同帧。 从这个角度出发， 组帧 方式可以被分为以下几种： 字符计数法 字符计数法 是在帧的首部设置一个计数字段，用来指示该帧中包含的字符（或字节）数量。 当接收方开始读取一帧时，首先读取位于 帧首部的计数字段 。通过该字段的数值，接收方即可知道该 帧的总长度 （即后续应读取的字符数）。随后，接收方按照得到的长度继续读取剩余的数据，直至完整地接收完本帧。 首位定界字符法 首位定界字符法即 使用特殊控制字符标志帧的开始和结束 。 但是使用这种方式可能出现如下问题：就是 首位定界字符 可能会在帧内部出现，这个时候就会造成歧义。 所以当特殊字符出现在帧的数据部分时，需要用 转义字符 来对特殊字符进行转义', sort_order = COALESCE(sort_order, 98)
WHERE id = 320;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (320, 'knowledge-html/csgraduates/computer-network/computer_network-datalink-framing.html', '组帧 💡 低优先级 较少考查，了解下几种组帧方法的原理即可。 数据链路层的主要功能之一就是 组帧 。 帧（frame）代表数据链路层的数据发送单位，在接收到来自于网络层的报文（packet）时如何为其添加帧头和帧尾，并且以何种方式进行 帧定界 （接收方区别连续不同的帧）。 组帧 的关键就在于 帧定界 ，也就是对于接收方来说，它能够以某种方式区分连续收到的不同帧。 从这个角度出发， 组帧 方式可以被分为以下几种： 字符计数法 字符计数法 是在帧的首部设置一个计数字段，用来指示该帧中包含的字符（或字节）数量。 当接收方开始读取一帧时，首先读取位于 帧首部的计数字段 。通过该字段的数值，接收方即可知道该 帧的总长度 （即后续应读取的字符数）。随后，接收方按照得到的长度继续读取剩余的数据，直至完整地接收完本帧。 首位定界字符法 首位定界字符法即 使用特殊控制字符标志帧的开始和结束 。 但是使用这种方式可能出现如下问题：就是 首位定界字符 可能会在帧内部出现，这个时候就会造成歧义。 所以当特殊字符出现在帧的数据部分时，需要用 转义字符 来对特殊字符进行转义', 'https://www.csgraduates.com/computer_network/datalink/framing/',
   'knowledge-assets/csgraduates/computer-network/computer_network-datalink-framing', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/framing/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink-framing.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink-framing", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink-framing.html", "html": true}')
