-- 计算机网络 / 局域网和广域网
SET @kp_id := 324;
UPDATE knowledge_point
SET description = '局域网和广域网 ⭐ 中优先级 真题练习 本节主要关注以太网的传输介质和帧格式，往年在解答题出现了传输介质的名称，如果不知道对应的带宽就难搞了。VLAN 和 广域网的概念考查频率低一些，但也比较简单，熟悉下能在选择题应对就可。 局域网 局域网（Local Area Network，LAN）是一种覆盖范围较小、用于连接同一物理地点（如家庭、办公室、学校或企业内）的计算机和其他设备的计算机网络。 特性 局域网的特性主要由三个要素决定： 拓扑结构 、 传输介质 和 介质访问控制方式 ，其中 介质访问控制方式 是最关键的因素，它决定了局域网的主要技术特性。 常见的局域网 拓扑结构 主要包括以下四类： 星形结构 环形结构 总线形结构 星形与总线形结合的复合型结构 在 传输介质 方面，局域网可以采用铜缆、双绞线和光纤等多种介质，其中 双绞线 是当前的主流传输介质。 局域网常用的 介质访问控制方法 包括 CSMA/CD 协议 、 令牌总线协议 和 令牌环协议 。其中，CSMA/CD 协议和令牌总线协议主要应用于总线形局域网，而令牌环协议则主要用于环形局域网。 实', sort_order = COALESCE(sort_order, 99)
WHERE id = 324;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (324, 'knowledge-html/csgraduates/computer-network/computer_network-datalink-lan.html', '局域网和广域网 ⭐ 中优先级 真题练习 本节主要关注以太网的传输介质和帧格式，往年在解答题出现了传输介质的名称，如果不知道对应的带宽就难搞了。VLAN 和 广域网的概念考查频率低一些，但也比较简单，熟悉下能在选择题应对就可。 局域网 局域网（Local Area Network，LAN）是一种覆盖范围较小、用于连接同一物理地点（如家庭、办公室、学校或企业内）的计算机和其他设备的计算机网络。 特性 局域网的特性主要由三个要素决定： 拓扑结构 、 传输介质 和 介质访问控制方式 ，其中 介质访问控制方式 是最关键的因素，它决定了局域网的主要技术特性。 常见的局域网 拓扑结构 主要包括以下四类： 星形结构 环形结构 总线形结构 星形与总线形结合的复合型结构 在 传输介质 方面，局域网可以采用铜缆、双绞线和光纤等多种介质，其中 双绞线 是当前的主流传输介质。 局域网常用的 介质访问控制方法 包括 CSMA/CD 协议 、 令牌总线协议 和 令牌环协议 。其中，CSMA/CD 协议和令牌总线协议主要应用于总线形局域网，而令牌环协议则主要用于环形局域网。 实', 'https://www.csgraduates.com/computer_network/datalink/lan/',
   'knowledge-assets/csgraduates/computer-network/computer_network-datalink-lan', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/lan/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink-lan.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink-lan", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink-lan.html", "html": true}')
