-- 计算机网络 / 介质访问控制
SET @kp_id := 323;
UPDATE knowledge_point
SET description = '介质访问控制 🔥 高优先级 真题练习 数据链路层的另一个重点（之前一个是 ARQ 协议），重点掌握 CSMA/CD 的细节，会在选择题和解答题中考查。多路复用和 CSMA/CA 也要熟悉下，会在选择题中考查。 ALOHA 协议说实话没考察过，但是出现过在考纲中，所以还是加在教程中。 共享介质 在介绍 MAC 概念之前，必须要说明一下 共享介质 的概念。 在一个网络环境中，多个设备可能需要同时访问同一个 物理介质 来发送数据，这个介质可以是 电缆 、 光纤 或者 无线信道 。 当设备发送数据时，数据包会在整个介质上传播，所有连接到该介质的设备都可以接收到数据包。 如果多个设备同时发送数据，介质上的数据信号就会相互 冲突 进而导致错误。 所以 MAC 协议确保了 共享介质 上的有效、公正且有序的数据传输。 注意 其实现代网络架构很少有这种共享介质了，但是考研的语境下，只要题目出现： CSMA/CD 冲突（collision） 传播时延 最小帧长 你就要立刻切换到这个模型： 共享信道 + 广播传播 + 半双工 所有设备接在同一根“线”上 一个设备在一个', sort_order = COALESCE(sort_order, 100)
WHERE id = 323;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (323, 'knowledge-html/csgraduates/computer-network/computer_network-datalink-mac.html', '介质访问控制 🔥 高优先级 真题练习 数据链路层的另一个重点（之前一个是 ARQ 协议），重点掌握 CSMA/CD 的细节，会在选择题和解答题中考查。多路复用和 CSMA/CA 也要熟悉下，会在选择题中考查。 ALOHA 协议说实话没考察过，但是出现过在考纲中，所以还是加在教程中。 共享介质 在介绍 MAC 概念之前，必须要说明一下 共享介质 的概念。 在一个网络环境中，多个设备可能需要同时访问同一个 物理介质 来发送数据，这个介质可以是 电缆 、 光纤 或者 无线信道 。 当设备发送数据时，数据包会在整个介质上传播，所有连接到该介质的设备都可以接收到数据包。 如果多个设备同时发送数据，介质上的数据信号就会相互 冲突 进而导致错误。 所以 MAC 协议确保了 共享介质 上的有效、公正且有序的数据传输。 注意 其实现代网络架构很少有这种共享介质了，但是考研的语境下，只要题目出现： CSMA/CD 冲突（collision） 传播时延 最小帧长 你就要立刻切换到这个模型： 共享信道 + 广播传播 + 半双工 所有设备接在同一根“线”上 一个设备在一个', 'https://www.csgraduates.com/computer_network/datalink/mac/',
   'knowledge-assets/csgraduates/computer-network/computer_network-datalink-mac', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/datalink/mac/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-datalink-mac.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-datalink-mac", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-datalink-mac.html", "html": true}')
