-- 计算机网络 / ARP
SET @kp_id := 330;
UPDATE knowledge_point
SET description = 'ARP ⭐ 中优先级 真题练习 需要掌握 ARP 的流程，选择题和解答题都会涉及到。 概念 ARP （Address Resolution Protocol，地址解析协议） 是一种在 TCP/IP 网络 中使用的协议，用于将 IP 地址 转换为 物理硬件地址 （例如， MAC 地址 ）。ARP 的主要目的是确定要通过网络传输数据的目标设备的 物理硬件地址 ，以便将数据帧正确地传送到目标设备。 流程 以上图为例，主机 用 ARP 协议查找主机 的 MAC 地址，其流程如下图所示 具体而言，一次 ARP 请求可以被拆分为 如下步骤 ： ARP 请求 当一台设备（我们称它为主机 A）需要发送数据包到同一局域网内的另一台设备（主机 B），但它只知道目标设备的 IP 地址 时，它会在本地网络上广播一个 ARP 请求 。这个请求的语义大致是这样的：“我拥有 IP 地址 X.X.X.X 的设备，请告诉我你的物理 MAC 地址。” ARP 请求的 目的 MAC 地址 为 ， 源 MAC 地址 设置为自己的 MAC 地址。 网络上的广播 ARP 请求是一个 广播帧', sort_order = COALESCE(sort_order, 101)
WHERE id = 330;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (330, 'knowledge-html/csgraduates/computer-network/computer_network-network-arp.html', 'ARP ⭐ 中优先级 真题练习 需要掌握 ARP 的流程，选择题和解答题都会涉及到。 概念 ARP （Address Resolution Protocol，地址解析协议） 是一种在 TCP/IP 网络 中使用的协议，用于将 IP 地址 转换为 物理硬件地址 （例如， MAC 地址 ）。ARP 的主要目的是确定要通过网络传输数据的目标设备的 物理硬件地址 ，以便将数据帧正确地传送到目标设备。 流程 以上图为例，主机 用 ARP 协议查找主机 的 MAC 地址，其流程如下图所示 具体而言，一次 ARP 请求可以被拆分为 如下步骤 ： ARP 请求 当一台设备（我们称它为主机 A）需要发送数据包到同一局域网内的另一台设备（主机 B），但它只知道目标设备的 IP 地址 时，它会在本地网络上广播一个 ARP 请求 。这个请求的语义大致是这样的：“我拥有 IP 地址 X.X.X.X 的设备，请告诉我你的物理 MAC 地址。” ARP 请求的 目的 MAC 地址 为 ， 源 MAC 地址 设置为自己的 MAC 地址。 网络上的广播 ARP 请求是一个 广播帧', 'https://www.csgraduates.com/computer_network/network/arp/',
   'knowledge-assets/csgraduates/computer-network/computer_network-network-arp', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/network/arp/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-network-arp.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-network-arp", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-network-arp.html", "html": true}')
