-- 计算机网络 / 网络层设备
SET @kp_id := 333;
UPDATE knowledge_point
SET description = '网络层设备 🔥 高优先级 真题练习 掌握路由器的组成和功能，以及掌握路由表的画法，会在选择题和解答题中考察。 路由器 路由器 （Router）是一种实现网络互连的设备，在 OSI 网络模型中的第三层，提供 路由 与 转发 的两种重要机制；可以决定数据包从来源端到目的端所经过的路由路径，这个过程称为 路由 ；将路由器输入端的数据包移至适当路由器输出端，称为 转发 。 组成 简单来说，路由器主要由以下软硬件组成： 硬件： CPU ：运行操作系统，处理 路由协议 。 交换结构 ：高速传输数据包，连接输入输出端口。 网络接口 ：以太网、光纤等，收发数据包。 软件： 操作系统 ：运行专用的嵌入式 操作系统 ，提供 路由协议 支持、配置管理等功能。 路由表 路由表 是路由器内部的数据结构，其中包含了有关网络之间如何进行 路由 的信息。 路由表 是根据 路由协议 （如 RIP、OSPF、BGP 等）和手动配置动态生成和维护的。 路由表包含如下信息： 目标网络 （Network Destination）：表示数据包要传递到的目标网络或主机。 子网掩码 （Netw', sort_order = COALESCE(sort_order, 102)
WHERE id = 333;
