-- 计算机网络 / DHCP
SET @kp_id := 329;
UPDATE knowledge_point
SET description = 'DHCP ⭐ 中优先级 真题练习 需掌握 DHCP 的功能和流程，可能在选择题中考察，也会在大题中考查一小问。 动态主机配置协议（DHCP）是一个网络管理协议，用于自动分配 IP 地址 和其他网络配置参数给网络设备，从而允许它们连接到 IP 网络 。 当你连接到一个网络中时，不管是通过 无线网 ，还是在电脑上连接了 以太网线 ，你会发现无需任何配置，你自动获取了一个 IP 地址 ，并可以通过该 IP 地址进行网络通信。 DHCP 的工作流程通常包括以下四个步骤，这个过程也被称作 DORA 过程，即 Discover , Offer , Request , 和 Acknowledgment 。 Discover : 客户端通过网络 广播 一个 DHCP DISCOVER 消息，请求可用的网络配置信息。因为客户端还没有分配到 IP 地址 ，所以这个消息的 源 IP 地址 是 0.0.0.0 ， 目的 IP 地址 是 255.255.255.255 。 Offer : 网络上的 DHCP 服务器接收到 DHCP DISCOVER 消息后，会向客户端发送', sort_order = COALESCE(sort_order, 103)
WHERE id = 329;
