-- 计算机网络 / ICMP
SET @kp_id := 328;
UPDATE knowledge_point
SET description = 'ICMP 💡 低优先级 真题练习 在选择题中考查，频率不高，关注下差错报文的类型以及 icmp 的应用。 ICMP （Internet Control Message Protocol）是一个 网络层协议 用于在 IP 主机和路由器之间发送 控制消息 。 ICMP 是 Internet 协议套件的 重要组成部分 ，它主要用于 诊断 和 报告错误 和某些特定条件。 首部 类型 ： 8 位 用于指定 ICMP 消息 的类型。 例如， 的类型为 ， 的类型为 。 代码 ： 8 位 为更进一步 细分 某个特定类型的 ICMP 消息而设置。 例如，对于 “目的地不可达” （ ）类型的消息，代码可以用来指定具体的不可达原因，如网络不可达、主机不可达等。 检验和 ： 16 位 用于验证 ICMP 消息在传输过程中没有被损坏。这个检验和涵盖了整个 ICMP 消息。 其它字段 这些字段的内容取决于 ICMP 消息 的 类型 和 代码 。 例如，对于 和 消息，接下来的字段包括一个标识符（ ）和一个序列号（ ）。 消息类型 ICMP 的消息类型可以分为 差错报文 和', sort_order = COALESCE(sort_order, 104)
WHERE id = 328;
