-- 计算机网络 / IP
SET @kp_id := 327;
UPDATE knowledge_point
SET description = 'IP 🔥 高优先级 真题练习 绝对重点，需要掌握 IPv4 协议中各个知识点的细节。IPv6 和 移动IP 简单了解一下基本概念，有小概率会在选择题中考察一题。 在现实生活中，我们通过“国家‑省份‑城市‑街道‑小区‑楼栋‑门号”等层级信息来定位一个具体地点，例如 中国‑北京市‑海淀区‑某街道‑某小区‑某栋‑某户。 在计算机网络里，定位一台主机同样需要使用唯一的地址，这个地址就是 IP 地址 。IP（Internet Protocol）直译为“互联网协议”，它既提供了主机的标识，又规定了数据在网络中的传输方式。 仅有地址并不能保证数据能够顺利从源端到达目的端。互联网是一张由无数路由器、交换机等网络设备相互连接而成的全球性网络。从 一个机器 到 另一个机器 的通信，往往要经过多级转发。如何在众多可能的路径中找到一条通向正确目的地的路线，就需要 IP 协议 与路由协议共同配合完成。后续章节我们会逐步剖析这一过程的细节。 目前 IP 协议有两个版本： IPv4（Internet Protocol Version 4） IPv6（Internet Prot', sort_order = COALESCE(sort_order, 105)
WHERE id = 327;
