-- 计算机网络 / 网络设备总结
SET @kp_id := 312;
UPDATE knowledge_point
SET description = '网络设备总结 ⭐ 中优先级 需要掌握不同层次网络设备的功能，哪些能够隔离冲突域，哪些能够隔离广播域，在解答题中常间接考察该知识。 冲突域 冲突域 是指在以太网中，当两个设备同时发送数据时， 可能发生冲突的一组网络设备所组成的区域 。在这个区域内，如果两个或多个设备同时发送帧，由于 共享介质 ，就会产生数据冲突，导致通信失败，需要重新发送。 📌 冲突发生的根本原因： 以太网（尤其是早期使用 共享总线 或 集线器 的方式）采用了 CSMA/CD 协议 （载波监听多路访问/冲突检测） 协议： 每个设备发送前先监听是否有信号； 如果发现没人发，就开始发； 如果两个设备几乎同时监听到空闲并发送，就会发生 冲突 。 冲突域的边界由 二层设备（如集线器和交换机） 决定： 集线器 （Hub）：所有端口共享同一个冲突域。连接在集线器上的设备同时发送数据会发生碰撞，因此无法隔离冲突域。 交换机 （Switch）：每个端口形成独立冲突域，设备之间的发送不会互相干扰，从而有效隔离冲突。 广播域 广播域 指通过广播方式发送的数据包能够到达的所有主机组成的网络范围。通常，我', sort_order = COALESCE(sort_order, 108)
WHERE id = 312;
