  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (311, 'knowledge-html/csgraduates/computer-network/computer_network-overall-iso.html', '分层结构 🔥 高优先级 真题练习 OSI 模型是选择题的高频考点，需要理解每一层的功能。此外，还需要了解 TCP/IP 协议栈和 OSI 协议栈的不同 以及 协议数据单元的概念。 ISO/OSI 模型 OSI 参考模型 有 7 层 ，自下而上依次为【物理层、数据链路层、网络层、传输层、会话层、表示层、应用层】（记忆：物链网输会示用）。低三层统称为 通信子网 ，它是为了联网而附加的通信设备，完成数据的传输功能；高三层统称为 资源子网 ，它相当于计算机系统，完成数据的处理等功能。 传输层 承上启下。 OSI 参考模型的层次结构如下图所示： 物理层 物理层的传输单位是 比特 ，功能是在物理媒体上为数据端设备透明地传输原始比特流，不用参与数据封装工作。为了实现该功能，物理层需要定义 硬件设备标准 ，如电缆类型、接口类型、电压标准等。 数据链路层 数据链路层的传输单位是 帧 ，两台主机之间的数据传输总是在一段一段的链路上传送的，这就需要使用专门的链路层协议。 数据链路层将网络层交来的 IP 分组封装成帧，并且可靠地传输到相邻结点的网络层。主要作用是加强物理', 'https://www.csgraduates.com/computer_network/overall/iso/',
   'knowledge-assets/csgraduates/computer-network/computer_network-overall-iso', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/overall/iso/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-overall-iso.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-overall-iso", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-overall-iso.html", "html": true}')
