-- 计算机网络 / 各层协议总结
SET @kp_id := 313;
UPDATE knowledge_point
SET description = '各层协议总结 💡 低优先级 这节还是作为计算机网络各层协议的一个概览，具体协议细节还是到相应章节去看。在本节中关注以下几点：1. 应用层协议的端口和下层传输层协议是什么。2. 每一层具体有哪些协议。 网络协议要素 网络协议规定了通信双方交互的规则，主要包括以下三要素： 语法 ：定义信息的格式和结构（如报文结构、编码方式等） 语义 ：规定控制信息的含义和需要完成的操作 时序 ：定义事件的发生顺序和通信双方的协同工作方式（如请求与响应的先后顺序） 应用层协议 应用层协议直接面向用户，为应用程序之间的通信提供服务： 协议 端口号 依赖协议 简要说明 HTTP/HTTPS 80 / 443 TCP 超文本传输协议，用于网页浏览。HTTPS 是加密版本，基于 TLS/SSL。 FTP 20 / 21 TCP 文件传输协议，用于文件上传与下载。20 为数据通道，21 为控制通道。 SMTP 25 TCP 简单邮件传输协议，用于邮件的发送。 POP3 110 / 995 TCP 邮局协议，用于从邮件服务器接收邮件。995 是加密版本（POP3S）。 DNS 5', sort_order = COALESCE(sort_order, 110)
WHERE id = 313;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (313, 'knowledge-html/csgraduates/computer-network/computer_network-overall-protocol.html', '各层协议总结 💡 低优先级 这节还是作为计算机网络各层协议的一个概览，具体协议细节还是到相应章节去看。在本节中关注以下几点：1. 应用层协议的端口和下层传输层协议是什么。2. 每一层具体有哪些协议。 网络协议要素 网络协议规定了通信双方交互的规则，主要包括以下三要素： 语法 ：定义信息的格式和结构（如报文结构、编码方式等） 语义 ：规定控制信息的含义和需要完成的操作 时序 ：定义事件的发生顺序和通信双方的协同工作方式（如请求与响应的先后顺序） 应用层协议 应用层协议直接面向用户，为应用程序之间的通信提供服务： 协议 端口号 依赖协议 简要说明 HTTP/HTTPS 80 / 443 TCP 超文本传输协议，用于网页浏览。HTTPS 是加密版本，基于 TLS/SSL。 FTP 20 / 21 TCP 文件传输协议，用于文件上传与下载。20 为数据通道，21 为控制通道。 SMTP 25 TCP 简单邮件传输协议，用于邮件的发送。 POP3 110 / 995 TCP 邮局协议，用于从邮件服务器接收邮件。995 是加密版本（POP3S）。 DNS 5', 'https://www.csgraduates.com/computer_network/overall/protocol/',
   'knowledge-assets/csgraduates/computer-network/computer_network-overall-protocol', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/overall/protocol/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-overall-protocol.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-overall-protocol", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-overall-protocol.html", "html": true}')
