-- 计算机网络 / 通信概念
SET @kp_id := 315;
UPDATE knowledge_point
SET description = '通信概念 🔥 高优先级 真题练习 本节的几个知识点选择题常考：奈奎斯特定理、香农定理、通信指标和接口特性，需要掌握计算方法。 接口特性 物理层定义了设备之间如何通过电缆、无线等物理媒介进行通信。物理层具有以下四种 接口特性 ： 机械特性 ：描述物理连接设备的 外部物理形态和接口规范 ，主要包括： 接口的形状（如RJ45、USB等） 接口的引脚数量和排列顺序 电缆的类型（双绞线、光纤、同轴电缆等） 功能特性 ：说明各个 接口引脚具体的功能 ，例如： 哪个引脚负责发送数据（Tx） 哪个引脚负责接收数据（Rx） 哪些引脚用于控制信号，如握手（RTS/CTS） 过程特性 ：定义了在数据传输过程中，各种物理信号是 如何协作完成数据通信的过程 ，例如： 传输起始与终止的方式 信号同步的机制 比特之间如何区分（串行或并行） 电气特性 ：规定了物理层信号的 电气属性 ，包括： 电压的幅值（高电平/低电平） 电流大小 信号的传输速率和传输距离 信号的上升沿、下降沿 通信指标 信道 与 信道 相关的概念有四个，需要能够辨别这几个名词： 信道 (Channel) ：是', sort_order = COALESCE(sort_order, 111)
WHERE id = 315;
