-- 计算机网络 / 物理层设备
SET @kp_id := 318;
UPDATE knowledge_point
SET description = '物理层设备 ⭐ 中优先级 了解物理层设备类型和功能，常和其他层次设备进行综合性考查。 集线器 定义：集线器（Hub）是一个 物理层设备 ，用于将多台计算机或其他网络设备连接在一起，从而形成一个单一的网络段。 工作方式 ：当一个设备通过集线器发送数据时，数据会被 广播到 集线器的所有其他端口。每个连接到集线器的设备都会收到这些数据，但只有目标设备才会处理它。集线器本身不会分析或查看传输的数据。 局限性: 由于集线器将数据广播到所有设备，所以它可能导致 网络拥塞 。因此，在大型或流量较大的网络中，集线器已经被交换机所取代，交换机能够智能地将数据转发到目标设备。 中继器 定义 ：中继器是一个 物理层设备 ，用于 放大 或 再生 数字 信号 。 工作方式 ：在以太网或其他类型的网络中，数据在电缆上只能传输一定的距离，超过这个距离，信号会减弱或退化。中继器放置在这种距离的两端，用于接收退化的信号，放大或再生它，然后将它传输到下一段电缆。 应用 ：中继器被用于 扩展网络 的物理范围，超出了单一段 电缆 或 物理媒体 的限制。 网络适配器 定义 ：网络适配器 ', sort_order = COALESCE(sort_order, 112)
WHERE id = 318;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
