-- 计算机网络 / 编码和调制
SET @kp_id := 316;
UPDATE knowledge_point
SET description = '编码和调制 ⭐ 中优先级 真题练习 常在选择题中考查编码类型和调制概念，需要熟悉几种编码方式的电平特征和调制的思想。 在计算机网络中， 编码 和 调制 是数据传输的两个关键过程，它们的目标都是为了让 数字信息 （如二进制的 0 和 1）能够有效、准确地在 物理介质 （如双绞线、光纤、无线电波等）上传输。 编码类型 编码 （encoding）指的是把 数字信号 （0 和 1）转换成适合在 传输介质 上传输的电信号或光信号。常见的编码方式有以下几种： 编码方法 1 的表示 0 的表示 归零编码 （RZ） 在时钟周期内由高电平跳到低电平 在时钟周期中保持低电平 非归零编码 （NRZ） 时钟周期内保持高电平 时钟周期内保持低电平 反向不归零编码 （NRZI） 电平与上一个时钟周期保持一致 电平相比上一个时钟周期发生跳变 曼彻斯特编码 （Manchester Encoding） 在时钟周期内由高电平跳到低电平 在时钟周期中由低电平跳到高电平 差分曼彻斯特编码 （Differential Manchester Encoding） 电平变化与上一个时钟周期相反', sort_order = COALESCE(sort_order, 113)
WHERE id = 316;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (316, 'knowledge-html/csgraduates/computer-network/computer_network-physical-encoding.html', '编码和调制 ⭐ 中优先级 真题练习 常在选择题中考查编码类型和调制概念，需要熟悉几种编码方式的电平特征和调制的思想。 在计算机网络中， 编码 和 调制 是数据传输的两个关键过程，它们的目标都是为了让 数字信息 （如二进制的 0 和 1）能够有效、准确地在 物理介质 （如双绞线、光纤、无线电波等）上传输。 编码类型 编码 （encoding）指的是把 数字信号 （0 和 1）转换成适合在 传输介质 上传输的电信号或光信号。常见的编码方式有以下几种： 编码方法 1 的表示 0 的表示 归零编码 （RZ） 在时钟周期内由高电平跳到低电平 在时钟周期中保持低电平 非归零编码 （NRZ） 时钟周期内保持高电平 时钟周期内保持低电平 反向不归零编码 （NRZI） 电平与上一个时钟周期保持一致 电平相比上一个时钟周期发生跳变 曼彻斯特编码 （Manchester Encoding） 在时钟周期内由高电平跳到低电平 在时钟周期中由低电平跳到高电平 差分曼彻斯特编码 （Differential Manchester Encoding） 电平变化与上一个时钟周期相反', 'https://www.csgraduates.com/computer_network/physical/encoding/',
   'knowledge-assets/csgraduates/computer-network/computer_network-physical-encoding', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/physical/encoding/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-physical-encoding.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-physical-encoding", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-physical-encoding.html", "html": true}')
