-- 计算机网络 / 交换方式
SET @kp_id := 317;
UPDATE knowledge_point
SET description = '交换方式 ⭐ 中优先级 真题练习 历年真题选择题经常围绕三种交换方式的传输时间进行考查，当然也不排除未来在大题考查的可能性。这一节为理解性内容，需要理解基于比特流和存储转发方案的传输时间计算。 交换 交换方式 是指在通信网络中，数据从发送方传输到接收方时，网络节点（如交换机、路由器）处理和转发数据的方式。它决定了数据传输的路径、资源分配和效率。交换方式是通信网络设计的核心，直接影响网络的性能、时延和资源利用率。 电路交换 、 报文交换 和 分组交换 是三种主要方式，其中分组交换又可以进一步分为 数据报和虚电路 两种方式： 电路交换 电路交换 （Circuit Switching）是一种传统的通信方法，其中在发送方和接收方之间建立一个专用的通信路径（电路），该路径在整个通信过程中保持不变，其过程如下： 连接建立 ：发送方发起请求，通过交换设备（如电话交换机）在网络中为通信双方寻找并分配一条固定路径，建立端到端的专用电路。这需要信令系统协调。 数据传输 ：电路建立后，数据（语音、视频等）通过这条固定路径连续传输。整个通信期间，路径保持独占，即使没有数', sort_order = COALESCE(sort_order, 114)
WHERE id = 317;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (317, 'knowledge-html/csgraduates/computer-network/computer_network-physical-switching.html', '交换方式 ⭐ 中优先级 真题练习 历年真题选择题经常围绕三种交换方式的传输时间进行考查，当然也不排除未来在大题考查的可能性。这一节为理解性内容，需要理解基于比特流和存储转发方案的传输时间计算。 交换 交换方式 是指在通信网络中，数据从发送方传输到接收方时，网络节点（如交换机、路由器）处理和转发数据的方式。它决定了数据传输的路径、资源分配和效率。交换方式是通信网络设计的核心，直接影响网络的性能、时延和资源利用率。 电路交换 、 报文交换 和 分组交换 是三种主要方式，其中分组交换又可以进一步分为 数据报和虚电路 两种方式： 电路交换 电路交换 （Circuit Switching）是一种传统的通信方法，其中在发送方和接收方之间建立一个专用的通信路径（电路），该路径在整个通信过程中保持不变，其过程如下： 连接建立 ：发送方发起请求，通过交换设备（如电话交换机）在网络中为通信双方寻找并分配一条固定路径，建立端到端的专用电路。这需要信令系统协调。 数据传输 ：电路建立后，数据（语音、视频等）通过这条固定路径连续传输。整个通信期间，路径保持独占，即使没有数', 'https://www.csgraduates.com/computer_network/physical/switching/',
   'knowledge-assets/csgraduates/computer-network/computer_network-physical-switching', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/physical/switching/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-physical-switching.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-physical-switching", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-physical-switching.html", "html": true}')
