-- 计算机网络 / TCP
SET @kp_id := 335;
UPDATE knowledge_point
SET description = 'TCP 🔥 高优先级 非常重要，TCP 三次握手、四次挥手、滑动窗口、可靠传输、拥塞控制 都需要深入掌握细节，能够在思想上理解 TCP 的整个传输流程，这样才能应对有变化的选择题和解答题。 TCP 特点 面向连接 ：发送数据前后需要分别通过三次握手和四次挥手进行连接的建立和断开。 可靠交付 ：保证数据传输的无差错、不丢失、不重复、有序。 面向字节流 ：以滑动窗口的形式对字节按照顺序进行发送和接收。 全双工 ：通信双方在一个 TCP 连接中都可以发送和接收数据。 TCP 首部 源端口号 （Source Port）：16 位字段，指示发送端的端口号。 目标端口号 （Destination Port）：16 位字段，指示接收端的端口号。 序列号 （Sequence Number）：32 位字段，用于标识 TCP 报文段中第一个数据字节的序列号。这个字段用于实现 TCP 的可靠性机制，如数据的按序传递和重传。 确认号 （Acknowledgment Number）：32 位字段，如果设置了 ACK 标志位，该字段包含了期望接收的下一个数据字节的序列号。这', sort_order = COALESCE(sort_order, 115)
WHERE id = 335;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
VALUES
  (335, 'knowledge-html/csgraduates/computer-network/computer_network-transport-tcp.html', 'TCP 🔥 高优先级 非常重要，TCP 三次握手、四次挥手、滑动窗口、可靠传输、拥塞控制 都需要深入掌握细节，能够在思想上理解 TCP 的整个传输流程，这样才能应对有变化的选择题和解答题。 TCP 特点 面向连接 ：发送数据前后需要分别通过三次握手和四次挥手进行连接的建立和断开。 可靠交付 ：保证数据传输的无差错、不丢失、不重复、有序。 面向字节流 ：以滑动窗口的形式对字节按照顺序进行发送和接收。 全双工 ：通信双方在一个 TCP 连接中都可以发送和接收数据。 TCP 首部 源端口号 （Source Port）：16 位字段，指示发送端的端口号。 目标端口号 （Destination Port）：16 位字段，指示接收端的端口号。 序列号 （Sequence Number）：32 位字段，用于标识 TCP 报文段中第一个数据字节的序列号。这个字段用于实现 TCP 的可靠性机制，如数据的按序传递和重传。 确认号 （Acknowledgment Number）：32 位字段，如果设置了 ACK 标志位，该字段包含了期望接收的下一个数据字节的序列号。这', 'https://www.csgraduates.com/computer_network/transport/tcp/',
   'knowledge-assets/csgraduates/computer-network/computer_network-transport-tcp', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/transport/tcp/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-transport-tcp.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-transport-tcp", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-transport-tcp.html", "html": true}')
