-- 计算机网络 / UDP
SET @kp_id := 336;
UPDATE knowledge_point
SET description = 'UDP ⭐ 中优先级 真题练习 需要关注下 UDP 的首部字段、校验方法和应用场景，可能会在选择题考查。 UDP 数据报 UDP （User Datagram Protocol）首部的长度固定为 8 个字节 （64 位），不论 UDP 携带的数据量大小如何，其首部都保持不变。UDP 首部的各个字段如下： 源端口 （Source Port）：占用 2 个字节（16 位），用于标识发送方应用程序的端口号。 目标端口 （Destination Port）：占用 2 个字节（16 位），用于标识接收方应用程序的端口号。 长度 （Length）：占用 2 个字节（16 位），指示 UDP 数据报的总长度，包括首部和数据。因此，最小长度为 8 字节 。 校验和 （Checksum）：占用 2 个字节（16 位），用于检测 UDP 数据报在传输过程中是否受到损坏。 当传输层从 IP 层收到 UDP 数据报时，就根据首部中的 目的端口 ，把 UDP 数据报通过相应的端口，上交最后的终点——应用进程，如下图所示： 若接收方 UDP 发现收到的报文中的 目的端口号 ', sort_order = COALESCE(sort_order, 116)
WHERE id = 336;
INSERT INTO knowledge_content
  (knowledge_point_id, html_ref, summary_text, source_url, asset_dir, metadata)
