   'knowledge-assets/csgraduates/computer-network/computer_network-transport-udp', '{"sourceName": "csgraduates", "subjectName": "计算机网络", "sourceUrl": "https://www.csgraduates.com/computer_network/transport/udp/", "htmlRef": "knowledge-html/csgraduates/computer-network/computer_network-transport-udp.html", "assetDir": "knowledge-assets/csgraduates/computer-network/computer_network-transport-udp", "sourcePath": "knowledge-html-sources/csgraduates/computer-network/computer_network-transport-udp.html", "html": true}')
